// 项目实战“复刻面试自习室”第 15 关：GitHub、Google 第三方登录。
// 学习卡片由 .sites-runtime/cards/pj-oauth-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjOauth:AiLevel={id:'pj-oauth',title:'GitHub、Google 第三方登录',summary:'用 OAuth 2.0 授权码流程接入第三方登录：重定向、state 防 CSRF、后端换令牌取用户、第三方身份对应本站账号',lessons:[
  {title:'这一关做什么：用 GitHub、Google 账号登录',body:'很多人不想再记一个新密码，更愿意点“用 GitHub 登录”。这一关接入第三方登录：\n一、GET /auth/github/login：把浏览器带到 GitHub 的授权页面，用户点“同意”；\n二、GitHub 把浏览器带回 GET /auth/github/callback?code=…&state=…，我们的后端拿着 code 去 GitHub 换一个访问令牌，再用令牌取到 GitHub 上的用户信息；\n三、第一次来的用户，自动在我们这里建一个账号，并记下“这个 GitHub 用户对应我们的哪个用户”；以后再来，直接登录同一个账号；\n四、登录成功后，和第 9 关一样创建会话、设置 Cookie，回到首页。\nGoogle 的流程完全一样，只是地址和返回的用户信息格式不同，所以代码写成“通用的提供方（provider）配置 + 一套流程”，GitHub 和 Google 各填一份配置就行。'},
  {title:'OAuth 2.0 授权码流程',body:'第三方登录用的是 OAuth 2.0 的“授权码”（Authorization Code）流程，一共四步：\n一、我们的网站把用户重定向到 GitHub：https://github.com/login/oauth/authorize?client_id=…&redirect_uri=…&state=…&scope=…。client_id 是我们在 GitHub 上登记的应用编号，redirect_uri 是授权后要回到的地址；\n二、用户在 GitHub 上登录、点“同意”，GitHub 把浏览器重定向回 redirect_uri，带上一个一次性的 code；\n三、我们的后端（不是浏览器）拿 code、client_id 和 client_secret（应用密钥）去 GitHub 的令牌接口换 access_token；\n四、后端用 access_token 调用 GitHub 的用户接口，拿到用户的编号和名字。\n关键在第三步：client_secret 只在后端和 GitHub 之间传，浏览器从头到尾看不到它，也拿不到 access_token。浏览器上只经过了一次性的 code，就算被人看到，没有 client_secret 也换不到令牌。'},
  {title:'state：防止登录被劫持',body:'第一步重定向时，我们生成一个随机字符串 state，一份放进 URL，一份放进浏览器的 Cookie。GitHub 回调时会原样带回 state，后端比较 URL 里的 state 和 Cookie 里的是否一致，不一致就拒绝（400）。\n为什么要这样做？假设没有 state：坏人先用自己的 GitHub 账号走到第二步，拿到一个回调地址（带着他自己的 code），再诱导你点击这个地址。你的浏览器就会以坏人的身份登录我们的网站，你在上面记录的学习数据、填写的东西都进了坏人的账号。这种攻击叫“登录 CSRF”。\n有了 state，坏人的回调地址里的 state 和你浏览器 Cookie 里的对不上（你根本没有发起过登录），后端就会拒绝。state 的 Cookie 只需要活几分钟，用完就删。'},
  {title:'账号怎么对应：第三方身份表',body:'GitHub 用户和我们的用户是两套编号，需要一张表把它们对应起来：\noauth_accounts(provider, provider_user_id, user_id)：provider 是 github 或 google，provider_user_id 是对方给的用户编号，主键是 (provider, provider_user_id)。\n回调时先查这张表：查到了，直接登录对应的用户；查不到，说明是第一次来，就新建一个用户，再插一行对应关系。\n几个细节：\n一、要用对方的“用户编号”来对应，不要用用户名或邮箱：GitHub 用户可以改名，邮箱也可以换，编号永远不变；\n二、新用户的用户名用 gh_ 或 gg_ 前缀加上对方的名字，只保留字母、数字和下划线，最长 20 个字符；被占用了就在后面加几个随机数字；\n三、第三方注册的用户没有密码，password_hash 存空字符串。空字符串不是合法的哈希，所以用密码登录这个账号永远会失败，只能通过第三方登录。'},
  {title:'配置：应用编号、密钥和测试用的假服务',body:'要用真的 GitHub 登录，先去 GitHub 的 Settings → Developer settings → OAuth Apps 新建一个应用，回调地址填 http://localhost:8080/auth/github/callback，得到 Client ID 和 Client Secret。Google 在 Google Cloud 控制台的“凭据”里创建 OAuth 客户端。\n这些值都从环境变量读取：GITHUB_CLIENT_ID、GITHUB_CLIENT_SECRET、GOOGLE_CLIENT_ID、GOOGLE_CLIENT_SECRET，以及网站自己的地址 PUBLIC_URL（默认 http://localhost:8080，用来拼回调地址）。没有配置的提供方，登录地址返回 503。\n验收时不可能每次都真的去 GitHub 点同意。所以再加一个测试用的配置 OAUTH_MOCK_URL：设置了它，所有提供方的地址都换成 {OAUTH_MOCK_URL}/github/authorize、/github/token、/github/user 这样的假地址，验收脚本在那里启动一个假的授权服务。这种“通过配置把外部服务换成假的”的做法，和上一关的 AI_BASE_URL 是同一个思路。'},
  {title:'第三方登录的地址约定',body:'两个地址都是给浏览器直接打开的，返回的是重定向，不是 JSON（出错时才返回 JSON）。{provider} 是 github 或 google。',code:`GET /auth/{provider}/login
→ 302 Location: 授权页?client_id=…&redirect_uri=…&state=…&scope=…&response_type=code
   同时 Set-Cookie: oauth_state=随机值; Path=/auth; Max-Age=600; HttpOnly; SameSite=Lax
→ 404 不支持的提供方 / 503 还没有配置

GET /auth/{provider}/callback?code=…&state=…
→ 303 Location: /，同时设置 session Cookie（和第 9 关一样）
→ 400 state 和 Cookie 里的不一致
→ 502 和对方通信失败`,explain:[{at:'GET /auth/{provider}/login',to:'同时 Set-Cookie: oauth_state=随机值',text:'登录地址：把浏览器带到 GitHub 或 Google 的授权页，同时把 state 存进 Cookie。'},{at:'→ 404 不支持的提供方',text:'名字不认识 404；没设置应用编号和密钥 503。'},{at:'GET /auth/{provider}/callback?code=…&state=…',to:'→ 502 和对方通信失败',text:'回调地址：检查 state，用 code 换令牌、取用户、登录，最后回到首页。'}]},
  {title:'任务一：第三方身份的数据访问',body:'建 oauth_accounts 表，写“按第三方身份找用户”和“新建没有密码的用户并记下对应关系”两个操作。',variants:{go:{practice:{steps:['新建 internal/store/oauth.go，补完 TODO（import 里还要加上 "strings"）。','go build ./... 确认能编译。'],expect:'go build ./... 没有输出'},code:'// internal/store/oauth.go\npackage store\n\nimport (\n    "database/sql"\n    "errors"\n)\n\nconst oauthSchema = `CREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n)`\n\n// MigrateOAuth 建好 oauth_accounts 表。\nfunc (s *UserStore) MigrateOAuth() error {\n    _, err := s.db.Exec(oauthSchema)\n    return err\n}\n\n// UserByOAuth 按第三方身份找到对应的用户，没有时返回 ErrNotFound。\nfunc (s *UserStore) UserByOAuth(provider, providerUserID string) (User, error) {\n    var u User\n    err := s.db.QueryRow(`SELECT u.id, u.username, u.password_hash FROM oauth_accounts o\n        JOIN users u ON u.id = o.user_id WHERE o.provider = ? AND o.provider_user_id = ?`, provider, providerUserID).\n        Scan(&u.ID, &u.Username, &u.PasswordHash)\n    if errors.Is(err, sql.ErrNoRows) {\n        return User{}, ErrNotFound\n    }\n    return u, err\n}\n\n// CreateOAuthUser 新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里。\n// 用户名已被占用时返回 ErrUsernameTaken，调用方换一个名字再试。\nfunc (s *UserStore) CreateOAuthUser(username, provider, providerUserID string) (User, error) {\n    // TODO：开始事务；INSERT INTO users (username, password_hash) VALUES (?, \'\')，\n    //       错误信息包含 "UNIQUE" 时返回 ErrUsernameTaken；用 LastInsertId 拿到新用户的 id；\n    //       INSERT INTO oauth_accounts (provider, provider_user_id, user_id)；提交事务，返回新用户\n    return User{}, nil\n}',explain:[{at:'// internal/store/oauth.go',to:')',text:'第三方身份的数据访问，写成 UserStore 的方法，和用户表放在一起。'},{at:'const oauthSchema =',to:')`',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本：GitHub 的是数字，Google 的是很长的数字字符串。'},{at:'func (s *UserStore) MigrateOAuth() error {',to:'return err',text:'建表，main 启动时调用一次。'},{at:'func (s *UserStore) UserByOAuth(',to:'return u, err',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'func (s *UserStore) CreateOAuthUser(',to:'return User{}, nil',text:'新建第三方登录的用户，要你补全。'}],solution:{code:'// internal/store/oauth.go\npackage store\n\nimport (\n    "database/sql"\n    "errors"\n    "strings"\n)\n\nconst oauthSchema = `CREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n)`\n\n// MigrateOAuth 建好 oauth_accounts 表。\nfunc (s *UserStore) MigrateOAuth() error {\n    _, err := s.db.Exec(oauthSchema)\n    return err\n}\n\n// UserByOAuth 按第三方身份找到对应的用户，没有时返回 ErrNotFound。\nfunc (s *UserStore) UserByOAuth(provider, providerUserID string) (User, error) {\n    var u User\n    err := s.db.QueryRow(`SELECT u.id, u.username, u.password_hash FROM oauth_accounts o\n        JOIN users u ON u.id = o.user_id WHERE o.provider = ? AND o.provider_user_id = ?`, provider, providerUserID).\n        Scan(&u.ID, &u.Username, &u.PasswordHash)\n    if errors.Is(err, sql.ErrNoRows) {\n        return User{}, ErrNotFound\n    }\n    return u, err\n}\n\n// CreateOAuthUser 新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里。\n// 用户名已被占用时返回 ErrUsernameTaken，调用方换一个名字再试。\nfunc (s *UserStore) CreateOAuthUser(username, provider, providerUserID string) (User, error) {\n    tx, err := s.db.Begin()\n    if err != nil {\n        return User{}, err\n    }\n    defer tx.Rollback()\n    res, err := tx.Exec("INSERT INTO users (username, password_hash) VALUES (?, \'\')", username)\n    if err != nil {\n        if strings.Contains(err.Error(), "UNIQUE") {\n            return User{}, ErrUsernameTaken\n        }\n        return User{}, err\n    }\n    id, err := res.LastInsertId()\n    if err != nil {\n        return User{}, err\n    }\n    if _, err := tx.Exec("INSERT INTO oauth_accounts (provider, provider_user_id, user_id) VALUES (?, ?, ?)",\n        provider, providerUserID, id); err != nil {\n        return User{}, err\n    }\n    return User{ID: int(id), Username: username}, tx.Commit()\n}',explain:[{at:'// internal/store/oauth.go',to:')',text:'第三方身份的数据访问，写成 UserStore 的方法，和用户表放在一起。'},{at:'const oauthSchema =',to:')`',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本：GitHub 的是数字，Google 的是很长的数字字符串。'},{at:'func (s *UserStore) MigrateOAuth() error {',to:'return err',text:'建表，main 启动时调用一次。'},{at:'func (s *UserStore) UserByOAuth(',to:'return u, err',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'func (s *UserStore) CreateOAuthUser(',to:'defer tx.Rollback()',text:'两张表要么都写成功，要么都不写，放在一个事务里。'},{at:'res, err := tx.Exec("INSERT INTO users',to:'return User{}, err',text:'新建用户，密码哈希是空字符串：空字符串不是合法的 bcrypt 哈希，用密码登录这个账号永远会失败。用户名重复时返回 ErrUsernameTaken。'},{at:'id, err := res.LastInsertId()',to:'return User{}, err',text:'拿到新用户的编号。'},{at:'if _, err := tx.Exec("INSERT INTO oauth_accounts',to:'return User{ID: int(id), Username: username}, tx.Commit()',text:'记下对应关系，提交事务。'}]}},java:{practice:{steps:['按代码第一部分修改 schema.sql。','按第二部分在 UserRepository 里新增两个方法，补完 TODO（需要导入 org.springframework.transaction.annotation.Transactional）。'],expect:'IDEA 里没有红色报错即可，下一个任务把它用起来'},code:'-- src/main/resources/schema.sql：在最后加上\nCREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n);\n\n// repository/UserRepository.java：新增下面两个方法\n// 按第三方身份找到对应的用户\npublic Optional<User> findByOAuth(String provider, String providerUserId) {\n    return jdbc.query("""\n        SELECT u.id, u.username, u.password_hash FROM oauth_accounts o JOIN users u ON u.id = o.user_id\n        WHERE o.provider = ? AND o.provider_user_id = ?""", MAPPER, provider, providerUserId).stream().findFirst();\n}\n\n// 新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里；用户名被占用时抛出 UsernameTakenException\n@Transactional\npublic User createOAuthUser(String username, String provider, String providerUserId) {\n    // TODO：INSERT INTO users (username, password_hash) VALUES (?, \'\')（UNIQUE 冲突的处理和第 9 关的 create 一样）；\n    //       用 findByUsername 查出新用户；INSERT INTO oauth_accounts (provider, provider_user_id, user_id)；返回新用户\n    return null;\n}',explain:[{at:'-- src/main/resources/schema.sql',to:');',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本。'},{at:'// repository/UserRepository.java',to:'public Optional<User> findByOAuth(',text:'在第 9 关的用户仓库里新增两个方法。'},{at:'return jdbc.query("""',to:'WHERE o.provider = ? AND o.provider_user_id = ?""", MAPPER, provider, providerUserId).stream().findFirst();',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'@Transactional',to:'return null;',text:'新建第三方登录的用户，要你补全。'}],solution:{code:'-- src/main/resources/schema.sql：在最后加上\nCREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n);\n\n// repository/UserRepository.java：新增下面两个方法\n// 按第三方身份找到对应的用户\npublic Optional<User> findByOAuth(String provider, String providerUserId) {\n    return jdbc.query("""\n        SELECT u.id, u.username, u.password_hash FROM oauth_accounts o JOIN users u ON u.id = o.user_id\n        WHERE o.provider = ? AND o.provider_user_id = ?""", MAPPER, provider, providerUserId).stream().findFirst();\n}\n\n// 新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里；用户名被占用时抛出 UsernameTakenException\n@Transactional\npublic User createOAuthUser(String username, String provider, String providerUserId) {\n    try {\n        jdbc.update("INSERT INTO users (username, password_hash) VALUES (?, \'\')", username);\n    } catch (DataAccessException e) {\n        if (String.valueOf(e.getMostSpecificCause().getMessage()).contains("UNIQUE")) {\n            throw new UsernameTakenException();\n        }\n        throw e;\n    }\n    User user = findByUsername(username).orElseThrow();\n    jdbc.update("INSERT INTO oauth_accounts (provider, provider_user_id, user_id) VALUES (?, ?, ?)",\n        provider, providerUserId, user.id());\n    return user;\n}',explain:[{at:'-- src/main/resources/schema.sql',to:');',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本。'},{at:'// repository/UserRepository.java',to:'public Optional<User> findByOAuth(',text:'在第 9 关的用户仓库里新增两个方法。'},{at:'return jdbc.query("""',to:'WHERE o.provider = ? AND o.provider_user_id = ?""", MAPPER, provider, providerUserId).stream().findFirst();',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'@Transactional',to:'throw e;',text:'两张表在一个事务里写。新用户的密码哈希是空字符串：BCrypt 认不出空字符串，用密码登录这个账号会失败。用户名重复时换成我们自己的异常，调用方换个名字再试。'},{at:'User user = findByUsername(username).orElseThrow();',to:'return user;',text:'查出新用户（拿到自动生成的 id），记下对应关系。'}]}},node:{practice:{steps:['新建 src/db/oauth.js，补完 TODO。'],expect:'文件保存好即可，下一个任务把它用起来'},code:'// src/db/oauth.js\nconst { db } = require("./database");\nconst { UsernameTakenError } = require("./users");\n\ndb.exec(`\n  CREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n  );\n`);\n\n// 按第三方身份找到对应的用户 { id, username }，没有时是 undefined\nfunction findUserByOAuth(provider, providerUserId) {\n  return db\n    .prepare(`SELECT u.id, u.username FROM oauth_accounts o JOIN users u ON u.id = o.user_id\n              WHERE o.provider = ? AND o.provider_user_id = ?`)\n    .get(provider, providerUserId);\n}\n\n// 新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里；用户名被占用时抛出 UsernameTakenError\nconst createOAuthUser = db.transaction((username, provider, providerUserId) => {\n  // TODO：INSERT INTO users (username, password_hash) VALUES (?, \'\')，\n  //       err.code 是 "SQLITE_CONSTRAINT_UNIQUE" 时抛出 UsernameTakenError；\n  //       INSERT INTO oauth_accounts (provider, provider_user_id, user_id)；返回 { id, username }\n});\n\nmodule.exports = { findUserByOAuth, createOAuthUser };',explain:[{at:'// src/db/oauth.js',to:'const { UsernameTakenError } = require("./users");',text:'第三方身份的数据访问。用户名重复的错误类型复用第 9 关的。'},{at:'db.exec(`',to:'`);',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本。'},{at:'function findUserByOAuth(',to:'.get(provider, providerUserId);',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'const createOAuthUser = db.transaction(',text:'新建第三方登录的用户，要你补全。'},{at:'module.exports =',text:'导出。'}],solution:{code:'// src/db/oauth.js\nconst { db } = require("./database");\nconst { UsernameTakenError } = require("./users");\n\ndb.exec(`\n  CREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n  );\n`);\n\n// 按第三方身份找到对应的用户 { id, username }，没有时是 undefined\nfunction findUserByOAuth(provider, providerUserId) {\n  return db\n    .prepare(`SELECT u.id, u.username FROM oauth_accounts o JOIN users u ON u.id = o.user_id\n              WHERE o.provider = ? AND o.provider_user_id = ?`)\n    .get(provider, providerUserId);\n}\n\n// 新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里；用户名被占用时抛出 UsernameTakenError\nconst createOAuthUser = db.transaction((username, provider, providerUserId) => {\n  let result;\n  try {\n    result = db.prepare("INSERT INTO users (username, password_hash) VALUES (?, \'\')").run(username);\n  } catch (err) {\n    if (err.code === "SQLITE_CONSTRAINT_UNIQUE") throw new UsernameTakenError();\n    throw err;\n  }\n  const id = Number(result.lastInsertRowid);\n  db.prepare("INSERT INTO oauth_accounts (provider, provider_user_id, user_id) VALUES (?, ?, ?)")\n    .run(provider, providerUserId, id);\n  return { id, username };\n});\n\nmodule.exports = { findUserByOAuth, createOAuthUser };',explain:[{at:'// src/db/oauth.js',to:'const { UsernameTakenError } = require("./users");',text:'第三方身份的数据访问。用户名重复的错误类型复用第 9 关的。'},{at:'db.exec(`',to:'`);',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本。'},{at:'function findUserByOAuth(',to:'.get(provider, providerUserId);',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'const createOAuthUser = db.transaction(',to:'throw err;',text:'新建用户，密码哈希是空字符串：它不是合法的“盐:哈希”格式，用密码登录这个账号会失败。用户名重复时抛出 UsernameTakenError，事务回滚。'},{at:'const id = Number(result.lastInsertRowid);',to:'return { id, username };',text:'拿到新用户的编号，记下对应关系。'},{at:'module.exports =',text:'导出。'}]}},python:{practice:{steps:['按代码第一部分在 SCHEMA 里加上 oauth_accounts 表。','新建 app/oauth_db.py，补完 TODO。'],expect:'文件保存好即可，下一个任务把它用起来'},code:'# app/database.py：在 SCHEMA 的最后加上\nCREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n);\n\n# app/oauth_db.py\nimport sqlite3\nfrom contextlib import closing\n\nfrom app.database import connect, query_one\nfrom app.users import UsernameTaken\n\n\ndef find_user_by_oauth(provider, provider_user_id):\n    """按第三方身份找到对应的用户 {"id", "username"}，没有时返回 None"""\n    return query_one(\n        "SELECT u.id, u.username FROM oauth_accounts o JOIN users u ON u.id = o.user_id "\n        "WHERE o.provider = ? AND o.provider_user_id = ?",\n        (provider, provider_user_id),\n    )\n\n\ndef create_oauth_user(username, provider, provider_user_id):\n    """新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里；用户名被占用时抛出 UsernameTaken"""\n    # TODO：用同一个连接、一个 with conn 事务：INSERT INTO users (username, password_hash) VALUES (?, \'\')，\n    #       用 .lastrowid 拿到新 id，再 INSERT INTO oauth_accounts；捕获 sqlite3.IntegrityError 改为抛出 UsernameTaken；\n    #       返回 {"id", "username"}\n    return None',explain:[{at:'# app/database.py',to:');',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本。'},{at:'# app/oauth_db.py',to:'from app.users import UsernameTaken',text:'第三方身份的数据访问。用户名重复的异常复用第 9 关的。'},{at:'def find_user_by_oauth(',to:'(provider, provider_user_id),',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'def create_oauth_user(',to:'return None',text:'新建第三方登录的用户，要你补全。'}],solution:{code:'# app/database.py：在 SCHEMA 的最后加上\nCREATE TABLE IF NOT EXISTS oauth_accounts (\n    provider         TEXT    NOT NULL,\n    provider_user_id TEXT    NOT NULL,\n    user_id          INTEGER NOT NULL REFERENCES users(id),\n    PRIMARY KEY (provider, provider_user_id)\n);\n\n# app/oauth_db.py\nimport sqlite3\nfrom contextlib import closing\n\nfrom app.database import connect, query_one\nfrom app.users import UsernameTaken\n\n\ndef find_user_by_oauth(provider, provider_user_id):\n    """按第三方身份找到对应的用户 {"id", "username"}，没有时返回 None"""\n    return query_one(\n        "SELECT u.id, u.username FROM oauth_accounts o JOIN users u ON u.id = o.user_id "\n        "WHERE o.provider = ? AND o.provider_user_id = ?",\n        (provider, provider_user_id),\n    )\n\n\ndef create_oauth_user(username, provider, provider_user_id):\n    """新建一个没有密码的用户，并记下第三方身份，两步放在一个事务里；用户名被占用时抛出 UsernameTaken"""\n    with closing(connect()) as conn:\n        try:\n            with conn:\n                uid = conn.execute("INSERT INTO users (username, password_hash) VALUES (?, \'\')", (username,)).lastrowid\n                conn.execute("INSERT INTO oauth_accounts (provider, provider_user_id, user_id) VALUES (?, ?, ?)",\n                             (provider, provider_user_id, uid))\n        except sqlite3.IntegrityError:\n            raise UsernameTaken() from None\n    return {"id": uid, "username": username}',explain:[{at:'# app/database.py',to:');',text:'对应关系表：哪个提供方的哪个用户编号，对应我们的哪个用户。(provider, provider_user_id) 做联合主键，同一个第三方身份只能对应一个账号。对方的编号统一存成文本。'},{at:'# app/oauth_db.py',to:'from app.users import UsernameTaken',text:'第三方身份的数据访问。用户名重复的异常复用第 9 关的。'},{at:'def find_user_by_oauth(',to:'(provider, provider_user_id),',text:'连接两张表：按提供方和对方的编号，找到我们的用户。'},{at:'def create_oauth_user(',to:'(provider, provider_user_id, uid))',text:'with conn 是一个事务：两条插入要么都成功，要么都回滚。新用户的密码哈希是空字符串，用密码登录这个账号会失败。'},{at:'except sqlite3.IntegrityError:',to:'raise UsernameTaken() from None',text:'用户名重复（违反 UNIQUE）时换成我们自己的异常，调用方换个名字再试。'},{at:'return {"id": uid, "username": username}',text:'返回新用户。'}]}}}},
  {title:'任务二：授权码流程',body:'业务逻辑层：提供方的配置（GitHub、Google 和测试用的假服务）、拼授权地址都已经给出；你来写回调的核心流程：换令牌、取用户信息、找到或新建用户、创建会话。',variants:{go:{practice:{steps:['新建 internal/service/oauth.go，读懂已经给出的部分，补完 TODO。','go build ./... 确认能编译。'],expect:'go build ./... 没有输出'},code:'// internal/service/oauth.go\npackage service\n\nimport (\n    "encoding/json"\n    "errors"\n    "fmt"\n    "math/rand/v2"\n    "net/http"\n    "net/url"\n    "os"\n    "regexp"\n    "strings"\n    "time"\n\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrUnknownProvider    = errors.New("不支持这种登录方式")\n    ErrProviderNotSetup   = errors.New("这种登录方式还没有配置")\n    ErrProviderFailed     = errors.New("第三方登录失败，请稍后再试")\n)\n\n// Provider 是一个第三方登录提供方的配置。\ntype Provider struct {\n    Name, AuthURL, TokenURL, UserURL, Scope, Prefix string\n    ClientID, ClientSecret                          string\n    IDField, NameField                              string\n}\n\ntype OAuthService struct {\n    providers map[string]Provider\n    users     *store.UserStore\n    publicURL string\n    http      *http.Client\n}\n\n// NewOAuthService 从环境变量读取 GitHub 和 Google 的配置；设置了 OAUTH_MOCK_URL 时，所有地址都换成假服务。\nfunc NewOAuthService(users *store.UserStore) *OAuthService {\n    providers := map[string]Provider{\n        "github": {Name: "github", Prefix: "gh_", Scope: "read:user", IDField: "id", NameField: "login",\n            AuthURL: "https://github.com/login/oauth/authorize", TokenURL: "https://github.com/login/oauth/access_token",\n            UserURL: "https://api.github.com/user"},\n        "google": {Name: "google", Prefix: "gg_", Scope: "openid profile email", IDField: "sub", NameField: "name",\n            AuthURL: "https://accounts.google.com/o/oauth2/v2/auth", TokenURL: "https://oauth2.googleapis.com/token",\n            UserURL: "https://openidconnect.googleapis.com/v1/userinfo"},\n    }\n    mock := strings.TrimRight(os.Getenv("OAUTH_MOCK_URL"), "/")\n    for name, p := range providers {\n        p.ClientID = os.Getenv(strings.ToUpper(name) + "_CLIENT_ID")\n        p.ClientSecret = os.Getenv(strings.ToUpper(name) + "_CLIENT_SECRET")\n        if mock != "" {\n            p.AuthURL, p.TokenURL, p.UserURL = mock+"/"+name+"/authorize", mock+"/"+name+"/token", mock+"/"+name+"/user"\n        }\n        providers[name] = p\n    }\n    publicURL := strings.TrimRight(os.Getenv("PUBLIC_URL"), "/")\n    if publicURL == "" {\n        publicURL = "http://localhost:8080"\n    }\n    return &OAuthService{providers: providers, users: users, publicURL: publicURL, http: &http.Client{Timeout: 15 * time.Second}}\n}\n\nfunc (s *OAuthService) provider(name string) (Provider, error) {\n    p, ok := s.providers[name]\n    if !ok {\n        return p, ErrUnknownProvider\n    }\n    if p.ClientID == "" || p.ClientSecret == "" {\n        return p, ErrProviderNotSetup\n    }\n    return p, nil\n}\n\nfunc (s *OAuthService) redirectURI(p Provider) string {\n    return s.publicURL + "/auth/" + p.Name + "/callback"\n}\n\n// LoginURL 拼出授权页的地址。\nfunc (s *OAuthService) LoginURL(name, state string) (string, error) {\n    p, err := s.provider(name)\n    if err != nil {\n        return "", err\n    }\n    q := url.Values{"client_id": {p.ClientID}, "redirect_uri": {s.redirectURI(p)}, "state": {state},\n        "scope": {p.Scope}, "response_type": {"code"}}\n    return p.AuthURL + "?" + q.Encode(), nil\n}\n\n// fetchJSON 发出请求，检查状态码，把 JSON 响应解析进 out。\nfunc (s *OAuthService) fetchJSON(req *http.Request, out any) error {\n    req.Header.Set("Accept", "application/json")\n    req.Header.Set("User-Agent", "zixishi")\n    resp, err := s.http.Do(req)\n    if err != nil {\n        return err\n    }\n    defer resp.Body.Close()\n    if resp.StatusCode != http.StatusOK {\n        return fmt.Errorf("%s 返回状态码 %d", req.URL, resp.StatusCode)\n    }\n    return json.NewDecoder(resp.Body).Decode(out)\n}\n\nvar notWordChar = regexp.MustCompile(`[^A-Za-z0-9_]`)\n\n// usernameFor 根据对方的名字生成我们的用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符。\nfunc usernameFor(p Provider, name string, retry int) string {\n    base := p.Prefix + notWordChar.ReplaceAllString(name, "")\n    if len(base) <= len(p.Prefix) {\n        base = p.Prefix + "user"\n    }\n    if retry > 0 {\n        return fmt.Sprintf("%.15s%d", base, 1000+rand.IntN(9000))\n    }\n    return fmt.Sprintf("%.20s", base)\n}\n\n// Callback 用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌。\nfunc (s *OAuthService) Callback(name, code string) (string, error) {\n    // TODO 1：取出提供方；用 POST 表单（client_id、client_secret、code、redirect_uri、grant_type=authorization_code）\n    //         请求 TokenURL，用 fetchJSON 解析出 access_token，失败或为空时返回 ErrProviderFailed（可以用 %w 包装细节）\n    // TODO 2：用 GET 请求 UserURL，请求头 Authorization: Bearer 令牌，解析成 map[string]any；\n    //         取出 IDField 对应的值作为对方的用户编号（JSON 数字解析出来是 float64，用 %.0f 转成没有小数的文字）\n    // TODO 3：s.users.UserByOAuth 找已有用户；ErrNotFound 时用 usernameFor 生成用户名，CreateOAuthUser 新建，\n    //         用户名被占用（ErrUsernameTaken）就换个名字重试，最多 5 次\n    // TODO 4：用第 9 关的 newToken() 生成会话令牌，s.users.CreateSession 保存（有效期 SessionTTL），返回令牌\n    return "", nil\n}',explain:[{at:'// internal/service/oauth.go',to:'"zixishi/internal/store"',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、发请求的小工具、生成用户名。最后的 Callback 要你写。'},{at:'var (',to:'ErrProviderFailed     = errors.New(',text:'三种错误：不支持的提供方（404）、没配置（503）、和对方通信失败（502）。'},{at:'type Provider struct {',to:'IDField, NameField',text:'一个提供方的配置：名字、三个地址、要申请的权限范围、用户名前缀、应用编号和密钥，以及“用户信息里哪个字段是编号、哪个是名字”。'},{at:'type OAuthService struct {',to:'http      *http.Client',text:'服务里放着所有提供方、用户仓库、网站自己的地址（拼回调地址用），以及一个带超时的 HTTP 客户端。'},{at:'func NewOAuthService(',to:'UserURL: "https://openidconnect.googleapis.com/v1/userinfo"},',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'mock := strings.TrimRight(',to:'providers[name] = p',text:'从环境变量读取应用编号和密钥（GITHUB_CLIENT_ID 这样，名字转成大写拼出来）。设置了 OAUTH_MOCK_URL 时，三个地址都换成假服务。map 里取出的是副本，改完要放回去。'},{at:'publicURL := strings.TrimRight(',to:'return &OAuthService{',text:'网站自己的地址，默认 http://localhost:8080，上线后改成真实域名。'},{at:'func (s *OAuthService) provider(',to:'return p, nil',text:'按名字取出提供方：不认识返回 ErrUnknownProvider，没配置编号和密钥返回 ErrProviderNotSetup。'},{at:'func (s *OAuthService) redirectURI(',to:'return s.publicURL',text:'回调地址：必须和在 GitHub、Google 上登记的完全一致。'},{at:'func (s *OAuthService) LoginURL(',to:'return p.AuthURL + "?" + q.Encode(), nil',text:'url.Values 是“参数名 → 值列表”，Encode 把它编码成 a=1&b=2，并且自动处理特殊字符。'},{at:'func (s *OAuthService) fetchJSON(',to:'return json.NewDecoder(resp.Body).Decode(out)',text:'和对方通信的小工具：要求返回 JSON（GitHub 默认返回表单格式）；GitHub 的接口要求必须带 User-Agent；检查状态码，再解析 JSON。'},{at:'var notWordChar =',text:'匹配“不是字母、数字、下划线”的字符。'},{at:'func usernameFor(',to:'return fmt.Sprintf("%.20s", base)',text:'生成用户名：去掉不合规的字符，%.20s 表示最多取 20 个字符。名字被占用时（retry > 0）取前 15 个字符，再加一个 4 位随机数。'},{at:'func (s *OAuthService) Callback(',to:'return "", nil',text:'回调的核心流程，要你补全。'}],solution:{code:'// internal/service/oauth.go\npackage service\n\nimport (\n    "encoding/json"\n    "errors"\n    "fmt"\n    "math/rand/v2"\n    "net/http"\n    "net/url"\n    "os"\n    "regexp"\n    "strings"\n    "time"\n\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrUnknownProvider    = errors.New("不支持这种登录方式")\n    ErrProviderNotSetup   = errors.New("这种登录方式还没有配置")\n    ErrProviderFailed     = errors.New("第三方登录失败，请稍后再试")\n)\n\n// Provider 是一个第三方登录提供方的配置。\ntype Provider struct {\n    Name, AuthURL, TokenURL, UserURL, Scope, Prefix string\n    ClientID, ClientSecret                          string\n    IDField, NameField                              string\n}\n\ntype OAuthService struct {\n    providers map[string]Provider\n    users     *store.UserStore\n    publicURL string\n    http      *http.Client\n}\n\n// NewOAuthService 从环境变量读取 GitHub 和 Google 的配置；设置了 OAUTH_MOCK_URL 时，所有地址都换成假服务。\nfunc NewOAuthService(users *store.UserStore) *OAuthService {\n    providers := map[string]Provider{\n        "github": {Name: "github", Prefix: "gh_", Scope: "read:user", IDField: "id", NameField: "login",\n            AuthURL: "https://github.com/login/oauth/authorize", TokenURL: "https://github.com/login/oauth/access_token",\n            UserURL: "https://api.github.com/user"},\n        "google": {Name: "google", Prefix: "gg_", Scope: "openid profile email", IDField: "sub", NameField: "name",\n            AuthURL: "https://accounts.google.com/o/oauth2/v2/auth", TokenURL: "https://oauth2.googleapis.com/token",\n            UserURL: "https://openidconnect.googleapis.com/v1/userinfo"},\n    }\n    mock := strings.TrimRight(os.Getenv("OAUTH_MOCK_URL"), "/")\n    for name, p := range providers {\n        p.ClientID = os.Getenv(strings.ToUpper(name) + "_CLIENT_ID")\n        p.ClientSecret = os.Getenv(strings.ToUpper(name) + "_CLIENT_SECRET")\n        if mock != "" {\n            p.AuthURL, p.TokenURL, p.UserURL = mock+"/"+name+"/authorize", mock+"/"+name+"/token", mock+"/"+name+"/user"\n        }\n        providers[name] = p\n    }\n    publicURL := strings.TrimRight(os.Getenv("PUBLIC_URL"), "/")\n    if publicURL == "" {\n        publicURL = "http://localhost:8080"\n    }\n    return &OAuthService{providers: providers, users: users, publicURL: publicURL, http: &http.Client{Timeout: 15 * time.Second}}\n}\n\nfunc (s *OAuthService) provider(name string) (Provider, error) {\n    p, ok := s.providers[name]\n    if !ok {\n        return p, ErrUnknownProvider\n    }\n    if p.ClientID == "" || p.ClientSecret == "" {\n        return p, ErrProviderNotSetup\n    }\n    return p, nil\n}\n\nfunc (s *OAuthService) redirectURI(p Provider) string {\n    return s.publicURL + "/auth/" + p.Name + "/callback"\n}\n\n// LoginURL 拼出授权页的地址。\nfunc (s *OAuthService) LoginURL(name, state string) (string, error) {\n    p, err := s.provider(name)\n    if err != nil {\n        return "", err\n    }\n    q := url.Values{"client_id": {p.ClientID}, "redirect_uri": {s.redirectURI(p)}, "state": {state},\n        "scope": {p.Scope}, "response_type": {"code"}}\n    return p.AuthURL + "?" + q.Encode(), nil\n}\n\n// fetchJSON 发出请求，检查状态码，把 JSON 响应解析进 out。\nfunc (s *OAuthService) fetchJSON(req *http.Request, out any) error {\n    req.Header.Set("Accept", "application/json")\n    req.Header.Set("User-Agent", "zixishi")\n    resp, err := s.http.Do(req)\n    if err != nil {\n        return err\n    }\n    defer resp.Body.Close()\n    if resp.StatusCode != http.StatusOK {\n        return fmt.Errorf("%s 返回状态码 %d", req.URL, resp.StatusCode)\n    }\n    return json.NewDecoder(resp.Body).Decode(out)\n}\n\nvar notWordChar = regexp.MustCompile(`[^A-Za-z0-9_]`)\n\n// usernameFor 根据对方的名字生成我们的用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符。\nfunc usernameFor(p Provider, name string, retry int) string {\n    base := p.Prefix + notWordChar.ReplaceAllString(name, "")\n    if len(base) <= len(p.Prefix) {\n        base = p.Prefix + "user"\n    }\n    if retry > 0 {\n        return fmt.Sprintf("%.15s%d", base, 1000+rand.IntN(9000))\n    }\n    return fmt.Sprintf("%.20s", base)\n}\n\n// Callback 用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌。\nfunc (s *OAuthService) Callback(name, code string) (string, error) {\n    p, err := s.provider(name)\n    if err != nil {\n        return "", err\n    }\n    form := url.Values{"client_id": {p.ClientID}, "client_secret": {p.ClientSecret}, "code": {code},\n        "redirect_uri": {s.redirectURI(p)}, "grant_type": {"authorization_code"}}\n    req, _ := http.NewRequest(http.MethodPost, p.TokenURL, strings.NewReader(form.Encode()))\n    req.Header.Set("Content-Type", "application/x-www-form-urlencoded")\n    var token struct {\n        AccessToken string `json:"access_token"`\n    }\n    if err := s.fetchJSON(req, &token); err != nil || token.AccessToken == "" {\n        return "", fmt.Errorf("%w：换令牌 %v", ErrProviderFailed, err)\n    }\n\n    req, _ = http.NewRequest(http.MethodGet, p.UserURL, nil)\n    req.Header.Set("Authorization", "Bearer "+token.AccessToken)\n    var info map[string]any\n    if err := s.fetchJSON(req, &info); err != nil {\n        return "", fmt.Errorf("%w：取用户信息 %v", ErrProviderFailed, err)\n    }\n    id := fmt.Sprint(info[p.IDField])\n    if info[p.IDField] == nil || id == "" {\n        return "", fmt.Errorf("%w：用户信息里没有 %s", ErrProviderFailed, p.IDField)\n    }\n    if n, ok := info[p.IDField].(float64); ok {\n        id = fmt.Sprintf("%.0f", n)\n    }\n\n    u, err := s.users.UserByOAuth(name, id)\n    if errors.Is(err, store.ErrNotFound) {\n        displayName, _ := info[p.NameField].(string)\n        for retry := 0; retry < 5; retry++ {\n            u, err = s.users.CreateOAuthUser(usernameFor(p, displayName, retry), name, id)\n            if !errors.Is(err, store.ErrUsernameTaken) {\n                break\n            }\n        }\n    }\n    if err != nil {\n        return "", err\n    }\n    session, err := newToken()\n    if err != nil {\n        return "", err\n    }\n    return session, s.users.CreateSession(session, u.ID, time.Now().Add(SessionTTL))\n}',explain:[{at:'// internal/service/oauth.go',to:'"zixishi/internal/store"',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、发请求的小工具、生成用户名。最后的 Callback 要你写。'},{at:'var (',to:'ErrProviderFailed     = errors.New(',text:'三种错误：不支持的提供方（404）、没配置（503）、和对方通信失败（502）。'},{at:'type Provider struct {',to:'IDField, NameField',text:'一个提供方的配置：名字、三个地址、要申请的权限范围、用户名前缀、应用编号和密钥，以及“用户信息里哪个字段是编号、哪个是名字”。'},{at:'type OAuthService struct {',to:'http      *http.Client',text:'服务里放着所有提供方、用户仓库、网站自己的地址（拼回调地址用），以及一个带超时的 HTTP 客户端。'},{at:'func NewOAuthService(',to:'UserURL: "https://openidconnect.googleapis.com/v1/userinfo"},',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'mock := strings.TrimRight(',to:'providers[name] = p',text:'从环境变量读取应用编号和密钥（GITHUB_CLIENT_ID 这样，名字转成大写拼出来）。设置了 OAUTH_MOCK_URL 时，三个地址都换成假服务。map 里取出的是副本，改完要放回去。'},{at:'publicURL := strings.TrimRight(',to:'return &OAuthService{',text:'网站自己的地址，默认 http://localhost:8080，上线后改成真实域名。'},{at:'func (s *OAuthService) provider(',to:'return p, nil',text:'按名字取出提供方：不认识返回 ErrUnknownProvider，没配置编号和密钥返回 ErrProviderNotSetup。'},{at:'func (s *OAuthService) redirectURI(',to:'return s.publicURL',text:'回调地址：必须和在 GitHub、Google 上登记的完全一致。'},{at:'func (s *OAuthService) LoginURL(',to:'return p.AuthURL + "?" + q.Encode(), nil',text:'url.Values 是“参数名 → 值列表”，Encode 把它编码成 a=1&b=2，并且自动处理特殊字符。'},{at:'func (s *OAuthService) fetchJSON(',to:'return json.NewDecoder(resp.Body).Decode(out)',text:'和对方通信的小工具：要求返回 JSON（GitHub 默认返回表单格式）；GitHub 的接口要求必须带 User-Agent；检查状态码，再解析 JSON。'},{at:'var notWordChar =',text:'匹配“不是字母、数字、下划线”的字符。'},{at:'func usernameFor(',to:'return fmt.Sprintf("%.20s", base)',text:'生成用户名：去掉不合规的字符，%.20s 表示最多取 20 个字符。名字被占用时（retry > 0）取前 15 个字符，再加一个 4 位随机数。'},{at:'func (s *OAuthService) Callback(',to:'return "", err',text:'取出提供方的配置。'},{at:'form := url.Values{',to:'return "", fmt.Errorf("%w：换令牌 %v", ErrProviderFailed, err)',text:'第三步：用授权码换令牌。OAuth 规定这个请求的正文是表单格式。client_secret 只在这里出现，浏览器看不到。%w 把 ErrProviderFailed 包进新错误里，上层用 errors.Is 还能认出它，同时日志里能看到细节。'},{at:'req, _ = http.NewRequest(http.MethodGet, p.UserURL, nil)',to:'return "", fmt.Errorf("%w：取用户信息 %v", ErrProviderFailed, err)',text:'第四步：用访问令牌取用户信息。两家返回的格式不同，先解析成通用的 map。'},{at:'id := fmt.Sprint(info[p.IDField])',to:'id = fmt.Sprintf("%.0f", n)',text:'取出对方的用户编号：没有就是出错了。JSON 里的数字解析成 float64，直接转文字可能变成 5.83231e+05 这种科学计数法，所以用 %.0f 转成整数形式。'},{at:'u, err := s.users.UserByOAuth(name, id)',to:'session, err := newToken()',text:'先找对应关系；第一次来的用户就新建账号，用户名被占用时换一个带随机数字的名字再试。'},{at:'session, err := newToken()',to:'return session, s.users.CreateSession(session, u.ID, time.Now().Add(SessionTTL))',text:'和密码登录一样：生成会话令牌、保存会话。'}]}},java:{practice:{steps:['新建 service/OAuthService.java，读懂已经给出的部分，补完 TODO。'],expect:'IDEA 里没有红色报错即可，下一个任务把它接到控制器上'},code:'// service/OAuthService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.repository.UserRepository;\nimport java.security.SecureRandom;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.HexFormat;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.client.SimpleClientHttpRequestFactory;\nimport org.springframework.stereotype.Service;\nimport org.springframework.util.LinkedMultiValueMap;\nimport org.springframework.web.client.RestClient;\nimport org.springframework.web.util.UriComponentsBuilder;\n\n@Service\npublic class OAuthService {\n\n    private static final Logger log = LoggerFactory.getLogger(OAuthService.class);\n\n    public record Provider(String name, String authUrl, String tokenUrl, String userUrl, String scope,\n                           String prefix, String idField, String nameField) {}\n\n    private static final Map<String, Provider> PROVIDERS = Map.of(\n        "github", new Provider("github", "https://github.com/login/oauth/authorize",\n            "https://github.com/login/oauth/access_token", "https://api.github.com/user", "read:user", "gh_", "id", "login"),\n        "google", new Provider("google", "https://accounts.google.com/o/oauth2/v2/auth",\n            "https://oauth2.googleapis.com/token", "https://openidconnect.googleapis.com/v1/userinfo",\n            "openid profile email", "gg_", "sub", "name"));\n\n    private final UserRepository users;\n    private final RestClient http;\n    private final SecureRandom random = new SecureRandom();\n\n    public OAuthService(UserRepository users) {\n        this.users = users;\n        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();\n        factory.setConnectTimeout(Duration.ofSeconds(10));\n        factory.setReadTimeout(Duration.ofSeconds(15));\n        this.http = RestClient.builder().requestFactory(factory).defaultHeader("User-Agent", "zixishi").build();\n    }\n\n    private static String env(String name, String def) {\n        String v = System.getenv(name);\n        return v == null || v.isBlank() ? def : v.replaceAll("/+$", "");\n    }\n\n    private static StudyService.StudyException error(int status, String message) {\n        return new StudyService.StudyException(status, message);\n    }\n\n    // 按名字取出提供方：设置了 OAUTH_MOCK_URL 时地址换成假服务；没有配置应用编号和密钥时 503\n    public Provider provider(String name) {\n        Provider p = PROVIDERS.get(name);\n        if (p == null) {\n            throw error(404, "不支持这种登录方式");\n        }\n        if (clientId(p).isEmpty() || clientSecret(p).isEmpty()) {\n            throw error(503, "这种登录方式还没有配置");\n        }\n        String mock = env("OAUTH_MOCK_URL", "");\n        if (!mock.isEmpty()) {\n            p = new Provider(p.name(), mock + "/" + name + "/authorize", mock + "/" + name + "/token",\n                mock + "/" + name + "/user", p.scope(), p.prefix(), p.idField(), p.nameField());\n        }\n        return p;\n    }\n\n    private static String clientId(Provider p) {\n        return env(p.name().toUpperCase() + "_CLIENT_ID", "");\n    }\n\n    private static String clientSecret(Provider p) {\n        return env(p.name().toUpperCase() + "_CLIENT_SECRET", "");\n    }\n\n    private static String redirectUri(Provider p) {\n        return env("PUBLIC_URL", "http://localhost:8080") + "/auth/" + p.name() + "/callback";\n    }\n\n    public String loginUrl(String name, String state) {\n        Provider p = provider(name);\n        return UriComponentsBuilder.fromUriString(p.authUrl())\n            .queryParam("client_id", clientId(p)).queryParam("redirect_uri", redirectUri(p))\n            .queryParam("state", state).queryParam("scope", p.scope()).queryParam("response_type", "code")\n            .encode().build().toUriString();\n    }\n\n    // 根据对方的名字生成用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符；重试时加随机数字\n    private String usernameFor(Provider p, Object name, int retry) {\n        String base = p.prefix() + String.valueOf(name == null ? "" : name).replaceAll("[^A-Za-z0-9_]", "");\n        if (base.length() <= p.prefix().length()) {\n            base = p.prefix() + "user";\n        }\n        if (retry > 0) {\n            return base.substring(0, Math.min(15, base.length())) + (1000 + random.nextInt(9000));\n        }\n        return base.substring(0, Math.min(20, base.length()));\n    }\n\n    // 回调：用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌\n    public String callback(String name, String code) {\n        // TODO 1：取出提供方；用 LinkedMultiValueMap 组装表单（client_id、client_secret、code、redirect_uri、grant_type=authorization_code），\n        //         http.post() 发到 tokenUrl（contentType 表单、accept JSON），body(Map.class) 取出 access_token；\n        //         再带 Authorization: Bearer 令牌 GET userUrl 取用户信息（Map）；任何一步出错都记日志并抛出 error(502, …)\n        // TODO 2：对方的用户编号是 info.get(idField)，没有时 502；JSON 数字要转成整数形式的文字\n        // TODO 3：users.findByOAuth 找已有用户；没有就用 usernameFor 生成用户名 createOAuthUser 新建，\n        //         遇到 UsernameTakenException 换个名字重试，最多 5 次\n        // TODO 4：生成 32 字节的随机会话令牌，users.createSession 保存（过期时间加上 AuthService.SESSION_TTL），返回令牌\n        return null;\n    }\n}',explain:[{at:'// service/OAuthService.java',to:'import org.springframework.web.util.UriComponentsBuilder;',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、生成用户名。最后的 callback 要你写。'},{at:'@Service',to:'private static final Logger log',text:'日志记录器。'},{at:'public record Provider(',to:'String prefix, String idField, String nameField) {}',text:'一个提供方的配置：名字、三个地址、要申请的权限范围、用户名前缀，以及“用户信息里哪个字段是编号、哪个是名字”。'},{at:'private static final Map<String, Provider> PROVIDERS',to:'"openid profile email", "gg_", "sub", "name"));',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'private final UserRepository users;',to:'this.http = RestClient.builder()',text:'依赖用户仓库；RestClient 设置好超时，并且每个请求都带上 User-Agent（GitHub 的接口要求必须有）。'},{at:'private static String env(',to:'return v == null',text:'读环境变量的小工具：没设置时用默认值，去掉末尾多余的 /。'},{at:'private static StudyService.StudyException error(',to:'return new StudyService.StudyException(status, message);',text:'业务错误继续复用 StudyException。'},{at:'public Provider provider(String name) {',to:'return p;',text:'按名字取出提供方：不认识 404，没配置 503；设置了 OAUTH_MOCK_URL 时，三个地址都换成假服务（record 不能修改，所以新建一个）。'},{at:'private static String clientId(',to:'return env("PUBLIC_URL", "http://localhost:8080") + "/auth/" + p.name() + "/callback";',text:'应用编号和密钥按 GITHUB_CLIENT_ID 这样的名字从环境变量读取；回调地址用网站自己的地址 PUBLIC_URL 拼出来，必须和在 GitHub、Google 上登记的一致。'},{at:'public String loginUrl(',to:'.encode().build().toUriString();',text:'UriComponentsBuilder 拼出授权页的地址，encode() 会处理特殊字符。'},{at:'private String usernameFor(',to:'return base.substring(0, Math.min(20, base.length()));',text:'生成用户名：去掉不合规的字符，最多 20 个字符；名字被占用时取前 15 个字符，再加一个 4 位随机数。'},{at:'public String callback(',to:'return null;',text:'回调的核心流程，要你补全。'}],solution:{code:'// service/OAuthService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.repository.UserRepository;\nimport java.security.SecureRandom;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.HexFormat;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.client.SimpleClientHttpRequestFactory;\nimport org.springframework.stereotype.Service;\nimport org.springframework.util.LinkedMultiValueMap;\nimport org.springframework.web.client.RestClient;\nimport org.springframework.web.util.UriComponentsBuilder;\n\n@Service\npublic class OAuthService {\n\n    private static final Logger log = LoggerFactory.getLogger(OAuthService.class);\n\n    public record Provider(String name, String authUrl, String tokenUrl, String userUrl, String scope,\n                           String prefix, String idField, String nameField) {}\n\n    private static final Map<String, Provider> PROVIDERS = Map.of(\n        "github", new Provider("github", "https://github.com/login/oauth/authorize",\n            "https://github.com/login/oauth/access_token", "https://api.github.com/user", "read:user", "gh_", "id", "login"),\n        "google", new Provider("google", "https://accounts.google.com/o/oauth2/v2/auth",\n            "https://oauth2.googleapis.com/token", "https://openidconnect.googleapis.com/v1/userinfo",\n            "openid profile email", "gg_", "sub", "name"));\n\n    private final UserRepository users;\n    private final RestClient http;\n    private final SecureRandom random = new SecureRandom();\n\n    public OAuthService(UserRepository users) {\n        this.users = users;\n        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();\n        factory.setConnectTimeout(Duration.ofSeconds(10));\n        factory.setReadTimeout(Duration.ofSeconds(15));\n        this.http = RestClient.builder().requestFactory(factory).defaultHeader("User-Agent", "zixishi").build();\n    }\n\n    private static String env(String name, String def) {\n        String v = System.getenv(name);\n        return v == null || v.isBlank() ? def : v.replaceAll("/+$", "");\n    }\n\n    private static StudyService.StudyException error(int status, String message) {\n        return new StudyService.StudyException(status, message);\n    }\n\n    // 按名字取出提供方：设置了 OAUTH_MOCK_URL 时地址换成假服务；没有配置应用编号和密钥时 503\n    public Provider provider(String name) {\n        Provider p = PROVIDERS.get(name);\n        if (p == null) {\n            throw error(404, "不支持这种登录方式");\n        }\n        if (clientId(p).isEmpty() || clientSecret(p).isEmpty()) {\n            throw error(503, "这种登录方式还没有配置");\n        }\n        String mock = env("OAUTH_MOCK_URL", "");\n        if (!mock.isEmpty()) {\n            p = new Provider(p.name(), mock + "/" + name + "/authorize", mock + "/" + name + "/token",\n                mock + "/" + name + "/user", p.scope(), p.prefix(), p.idField(), p.nameField());\n        }\n        return p;\n    }\n\n    private static String clientId(Provider p) {\n        return env(p.name().toUpperCase() + "_CLIENT_ID", "");\n    }\n\n    private static String clientSecret(Provider p) {\n        return env(p.name().toUpperCase() + "_CLIENT_SECRET", "");\n    }\n\n    private static String redirectUri(Provider p) {\n        return env("PUBLIC_URL", "http://localhost:8080") + "/auth/" + p.name() + "/callback";\n    }\n\n    public String loginUrl(String name, String state) {\n        Provider p = provider(name);\n        return UriComponentsBuilder.fromUriString(p.authUrl())\n            .queryParam("client_id", clientId(p)).queryParam("redirect_uri", redirectUri(p))\n            .queryParam("state", state).queryParam("scope", p.scope()).queryParam("response_type", "code")\n            .encode().build().toUriString();\n    }\n\n    // 根据对方的名字生成用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符；重试时加随机数字\n    private String usernameFor(Provider p, Object name, int retry) {\n        String base = p.prefix() + String.valueOf(name == null ? "" : name).replaceAll("[^A-Za-z0-9_]", "");\n        if (base.length() <= p.prefix().length()) {\n            base = p.prefix() + "user";\n        }\n        if (retry > 0) {\n            return base.substring(0, Math.min(15, base.length())) + (1000 + random.nextInt(9000));\n        }\n        return base.substring(0, Math.min(20, base.length()));\n    }\n\n    // 回调：用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌\n    public String callback(String name, String code) {\n        Provider p = provider(name);\n        Map<?, ?> info;\n        try {\n            LinkedMultiValueMap<String, String> form = new LinkedMultiValueMap<>();\n            form.add("client_id", clientId(p));\n            form.add("client_secret", clientSecret(p));\n            form.add("code", code == null ? "" : code);\n            form.add("redirect_uri", redirectUri(p));\n            form.add("grant_type", "authorization_code");\n            Map<?, ?> token = http.post().uri(p.tokenUrl()).contentType(MediaType.APPLICATION_FORM_URLENCODED)\n                .accept(MediaType.APPLICATION_JSON).body(form).retrieve().body(Map.class);\n            Object access = token == null ? null : token.get("access_token");\n            if (access == null) {\n                throw new IllegalStateException("没有拿到 access_token");\n            }\n            info = http.get().uri(p.userUrl()).header("Authorization", "Bearer " + access)\n                .accept(MediaType.APPLICATION_JSON).retrieve().body(Map.class);\n        } catch (RuntimeException e) {\n            log.error("第三方登录失败", e);\n            throw error(502, "第三方登录失败，请稍后再试");\n        }\n        Object rawId = info == null ? null : info.get(p.idField());\n        if (rawId == null) {\n            throw error(502, "第三方登录失败，请稍后再试");\n        }\n        String providerUserId = rawId instanceof Number n ? String.valueOf(n.longValue()) : rawId.toString();\n\n        User user = users.findByOAuth(name, providerUserId).orElse(null);\n        for (int retry = 0; user == null && retry < 5; retry++) {\n            try {\n                user = users.createOAuthUser(usernameFor(p, info.get(p.nameField()), retry), name, providerUserId);\n            } catch (UserRepository.UsernameTakenException e) {\n                // 用户名被占用，换一个再试\n            }\n        }\n        if (user == null) {\n            throw error(502, "第三方登录失败，请稍后再试");\n        }\n        byte[] bytes = new byte[32];\n        random.nextBytes(bytes);\n        String session = HexFormat.of().formatHex(bytes);\n        users.createSession(session, user.id(), Instant.now().plus(AuthService.SESSION_TTL));\n        return session;\n    }\n}',explain:[{at:'// service/OAuthService.java',to:'import org.springframework.web.util.UriComponentsBuilder;',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、生成用户名。最后的 callback 要你写。'},{at:'@Service',to:'private static final Logger log',text:'日志记录器。'},{at:'public record Provider(',to:'String prefix, String idField, String nameField) {}',text:'一个提供方的配置：名字、三个地址、要申请的权限范围、用户名前缀，以及“用户信息里哪个字段是编号、哪个是名字”。'},{at:'private static final Map<String, Provider> PROVIDERS',to:'"openid profile email", "gg_", "sub", "name"));',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'private final UserRepository users;',to:'this.http = RestClient.builder()',text:'依赖用户仓库；RestClient 设置好超时，并且每个请求都带上 User-Agent（GitHub 的接口要求必须有）。'},{at:'private static String env(',to:'return v == null',text:'读环境变量的小工具：没设置时用默认值，去掉末尾多余的 /。'},{at:'private static StudyService.StudyException error(',to:'return new StudyService.StudyException(status, message);',text:'业务错误继续复用 StudyException。'},{at:'public Provider provider(String name) {',to:'return p;',text:'按名字取出提供方：不认识 404，没配置 503；设置了 OAUTH_MOCK_URL 时，三个地址都换成假服务（record 不能修改，所以新建一个）。'},{at:'private static String clientId(',to:'return env("PUBLIC_URL", "http://localhost:8080") + "/auth/" + p.name() + "/callback";',text:'应用编号和密钥按 GITHUB_CLIENT_ID 这样的名字从环境变量读取；回调地址用网站自己的地址 PUBLIC_URL 拼出来，必须和在 GitHub、Google 上登记的一致。'},{at:'public String loginUrl(',to:'.encode().build().toUriString();',text:'UriComponentsBuilder 拼出授权页的地址，encode() 会处理特殊字符。'},{at:'private String usernameFor(',to:'return base.substring(0, Math.min(20, base.length()));',text:'生成用户名：去掉不合规的字符，最多 20 个字符；名字被占用时取前 15 个字符，再加一个 4 位随机数。'},{at:'public String callback(',to:'Map<?, ?> info;',text:'取出提供方的配置。'},{at:'try {',to:'throw error(502, "第三方登录失败，请稍后再试");',text:'用授权码换令牌（OAuth 规定正文是表单格式，LinkedMultiValueMap 配上表单的 contentType 就会按表单发送），再用令牌取用户信息。client_secret 只在这里出现，浏览器看不到。RestClient 遇到 4xx、5xx 会抛出异常，统一记日志、返回 502。'},{at:'Object rawId =',to:'String providerUserId =',text:'取出对方的用户编号：GitHub 的是数字（解析成 Number，转成不带小数的文字），Google 的是字符串。'},{at:'User user = users.findByOAuth(',to:'throw error(502, "第三方登录失败，请稍后再试");',text:'先找对应关系；第一次来就新建账号，用户名被占用时换一个带随机数字的名字再试。'},{at:'byte[] bytes = new byte[32];',to:'return session;',text:'和密码登录一样：生成会话令牌、保存会话。'}]}},node:{practice:{steps:['新建 src/services/oauth.js（代码第一部分），读懂已经给出的部分，补完 TODO。','新建 src/routes/oauth.js，按最后几行修改 app.js 和 src/services/auth.js 的 verifyPassword。','按验收卡片设置环境变量重启，浏览器打开 /auth/github/login 看看会跳到哪里。'],expect:'GET /auth/github/login\n→ 302 Location: http://127.0.0.1:8091/github/authorize?client_id=gh-id&redirect_uri=…&state=…'},code:'// src/services/oauth.js\nconst crypto = require("node:crypto");\nconst oauthDb = require("../db/oauth");\nconst users = require("../db/users");\nconst { SESSION_TTL } = require("./auth");\n\nclass OAuthError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst PROVIDERS = {\n  github: {\n    authUrl: "https://github.com/login/oauth/authorize",\n    tokenUrl: "https://github.com/login/oauth/access_token",\n    userUrl: "https://api.github.com/user",\n    scope: "read:user", prefix: "gh_", idField: "id", nameField: "login",\n  },\n  google: {\n    authUrl: "https://accounts.google.com/o/oauth2/v2/auth",\n    tokenUrl: "https://oauth2.googleapis.com/token",\n    userUrl: "https://openidconnect.googleapis.com/v1/userinfo",\n    scope: "openid profile email", prefix: "gg_", idField: "sub", nameField: "name",\n  },\n};\nconst MOCK = (process.env.OAUTH_MOCK_URL || "").replace(/\\/+$/, "");\nconst PUBLIC_URL = (process.env.PUBLIC_URL || "http://localhost:8080").replace(/\\/+$/, "");\n\n// 按名字取出提供方的完整配置：应用编号和密钥来自环境变量；设置了 OAUTH_MOCK_URL 时地址换成假服务\nfunction provider(name) {\n  const base = Object.hasOwn(PROVIDERS, name) ? PROVIDERS[name] : null;\n  if (!base) throw new OAuthError(404, "不支持这种登录方式");\n  const p = {\n    ...base,\n    name,\n    clientId: process.env[`${name.toUpperCase()}_CLIENT_ID`] || "",\n    clientSecret: process.env[`${name.toUpperCase()}_CLIENT_SECRET`] || "",\n    redirectUri: `${PUBLIC_URL}/auth/${name}/callback`,\n  };\n  if (MOCK) Object.assign(p, { authUrl: `${MOCK}/${name}/authorize`, tokenUrl: `${MOCK}/${name}/token`, userUrl: `${MOCK}/${name}/user` });\n  if (!p.clientId || !p.clientSecret) throw new OAuthError(503, "这种登录方式还没有配置");\n  return p;\n}\n\nfunction loginUrl(name, state) {\n  const p = provider(name);\n  const q = new URLSearchParams({ client_id: p.clientId, redirect_uri: p.redirectUri, state, scope: p.scope, response_type: "code" });\n  return `${p.authUrl}?${q}`;\n}\n\n// 和对方通信：要求返回 JSON，带上 User-Agent（GitHub 要求），检查状态码\nasync function fetchJSON(url, options) {\n  const res = await fetch(url, {\n    ...options,\n    headers: { Accept: "application/json", "User-Agent": "zixishi", ...options.headers },\n    signal: AbortSignal.timeout(15000),\n  });\n  if (!res.ok) throw new Error(`${url} 返回状态码 ${res.status}`);\n  return res.json();\n}\n\n// 根据对方的名字生成用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符；重试时加随机数字\nfunction usernameFor(p, name, retry) {\n  let base = p.prefix + String(name || "").replace(/[^A-Za-z0-9_]/g, "");\n  if (base.length <= p.prefix.length) base = p.prefix + "user";\n  return retry > 0 ? base.slice(0, 15) + crypto.randomInt(1000, 10000) : base.slice(0, 20);\n}\n\n// 回调：用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌\nasync function callback(name, code) {\n  // TODO 1：取出提供方；用 fetchJSON POST 表单（client_id、client_secret、code、redirect_uri、grant_type=authorization_code）\n  //         到 tokenUrl，取出 access_token；再带上 Authorization: Bearer 令牌 GET userUrl 取用户信息；\n  //         任何一步失败（try / catch）都记日志并抛出 OAuthError(502, "第三方登录失败，请稍后再试")\n  // TODO 2：对方的用户编号是 info[p.idField]，没有时同样 502；转成字符串\n  // TODO 3：oauthDb.findUserByOAuth 找已有用户；没有就用 usernameFor 生成用户名 createOAuthUser 新建，\n  //         遇到 UsernameTakenError 换个名字重试，最多 5 次\n  // TODO 4：生成 32 字节的随机会话令牌，users.createSession 保存（过期时间 Date.now() + SESSION_TTL），返回令牌\n}\n\nmodule.exports = { OAuthError, loginUrl, callback };\n\n// src/routes/oauth.js\nconst express = require("express");\nconst crypto = require("node:crypto");\nconst oauth = require("../services/oauth");\nconst { SESSION_TTL } = require("../services/auth");\n\nconst router = express.Router();\nconst STATE = { httpOnly: true, sameSite: "lax", path: "/auth" };\n\nfunction fail(err, res, next) {\n  if (err instanceof oauth.OAuthError) return res.status(err.status).json({ error: err.message });\n  next(err);\n}\n\nrouter.get("/:provider/login", (req, res, next) => {\n  try {\n    const state = crypto.randomBytes(16).toString("hex");\n    const target = oauth.loginUrl(req.params.provider, state);\n    res.cookie("oauth_state", state, { ...STATE, maxAge: 10 * 60 * 1000 });\n    res.redirect(302, target);\n  } catch (err) {\n    fail(err, res, next);\n  }\n});\n\nrouter.get("/:provider/callback", async (req, res, next) => {\n  const expected = req.cookies.oauth_state;\n  if (!expected || expected !== req.query.state) {\n    return res.status(400).json({ error: "登录请求已过期或不合法，请重新登录" });\n  }\n  res.clearCookie("oauth_state", STATE);\n  try {\n    const token = await oauth.callback(req.params.provider, req.query.code);\n    res.cookie("session", token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: SESSION_TTL });\n    res.redirect(303, "/");\n  } catch (err) {\n    fail(err, res, next);\n  }\n});\n\nmodule.exports = router;\n\n// app.js：在 app.use("/api", notFound) 前面挂上\napp.use("/auth", require("./src/routes/oauth"));\n\n// src/services/auth.js：verifyPassword 的第一行加上，第三方登录的用户没有密码，直接算错\nif (!stored.includes(":")) return false;',explain:[{at:'// src/services/oauth.js',to:'const { SESSION_TTL } = require("./auth");',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、发请求的小工具、生成用户名。最后的 callback 要你写。'},{at:'class OAuthError extends Error {',to:'this.status = status;',text:'业务错误带上状态码：不支持 404、没配置 503、和对方通信失败 502。'},{at:'const PROVIDERS = {',to:'};',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'const MOCK =',to:'const PUBLIC_URL =',text:'测试用的假服务地址；网站自己的地址（拼回调地址用），默认 http://localhost:8080，上线后改成真实域名。'},{at:'function provider(name) {',to:'return p;',text:'Object.hasOwn 判断这个名字是不是 PROVIDERS 自己的属性（避免 "toString" 这种名字取到对象自带的东西）。应用编号和密钥按 GITHUB_CLIENT_ID 这样的名字从环境变量读取；Object.assign 把假服务的地址覆盖上去。'},{at:'function loginUrl(name, state) {',to:'return `${p.authUrl}?${q}`;',text:'拼出授权页的地址，URLSearchParams 会自动编码参数。'},{at:'async function fetchJSON(url, options) {',to:'return res.json();',text:'和对方通信的小工具：要求返回 JSON（GitHub 默认返回表单格式），带上 User-Agent，15 秒超时，检查状态码。'},{at:'function usernameFor(p, name, retry) {',to:'return retry > 0 ?',text:'生成用户名：去掉不合规的字符，最多 20 个字符；名字被占用时取前 15 个字符，再加一个 4 位随机数。'},{at:'async function callback(name, code) {',text:'回调的核心流程，要你补全。'},{at:'module.exports = { OAuthError, loginUrl, callback };',text:'导出。'},{at:'// src/routes/oauth.js',to:'const STATE = { httpOnly: true, sameSite: "lax", path: "/auth" };',text:'第三方登录的两个地址，已经给出。它们是给浏览器直接打开的（会重定向），所以挂在 /auth 而不是 /api 下面。STATE 是 state Cookie 的选项：只在 /auth 下面有效。'},{at:'function fail(err, res, next) {',to:'next(err);',text:'业务错误按状态码返回，其他交给错误处理中间件。'},{at:'router.get("/:provider/login",',to:'fail(err, res, next);',text:'登录地址：生成随机 state，一份进 Cookie（10 分钟过期），一份拼进授权地址，然后 302 把浏览器带过去。SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。'},{at:'router.get("/:provider/callback",',to:'res.clearCookie("oauth_state", STATE);',text:'回调：Cookie 里的 state 和地址里的必须一致，防止登录 CSRF；用过就删。'},{at:'try {',to:'fail(err, res, next);',text:'换令牌、取用户、建会话都交给业务逻辑层；成功后设置会话 Cookie（和第 9 关一样的选项），303 回到首页。'},{at:'module.exports = router;',text:'导出路由。'},{at:'app.use("/auth", require("./src/routes/oauth"));',text:'挂在 /auth 下面。'},{at:'if (!stored.includes(":")) return false;',text:'第三方登录的用户密码哈希是空字符串，原来的 verifyPassword 拆不出盐和哈希会报错（变成 500）。没有冒号就直接返回“密码不对”。'}],solution:{code:'// src/services/oauth.js\nconst crypto = require("node:crypto");\nconst oauthDb = require("../db/oauth");\nconst users = require("../db/users");\nconst { SESSION_TTL } = require("./auth");\n\nclass OAuthError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst PROVIDERS = {\n  github: {\n    authUrl: "https://github.com/login/oauth/authorize",\n    tokenUrl: "https://github.com/login/oauth/access_token",\n    userUrl: "https://api.github.com/user",\n    scope: "read:user", prefix: "gh_", idField: "id", nameField: "login",\n  },\n  google: {\n    authUrl: "https://accounts.google.com/o/oauth2/v2/auth",\n    tokenUrl: "https://oauth2.googleapis.com/token",\n    userUrl: "https://openidconnect.googleapis.com/v1/userinfo",\n    scope: "openid profile email", prefix: "gg_", idField: "sub", nameField: "name",\n  },\n};\nconst MOCK = (process.env.OAUTH_MOCK_URL || "").replace(/\\/+$/, "");\nconst PUBLIC_URL = (process.env.PUBLIC_URL || "http://localhost:8080").replace(/\\/+$/, "");\n\n// 按名字取出提供方的完整配置：应用编号和密钥来自环境变量；设置了 OAUTH_MOCK_URL 时地址换成假服务\nfunction provider(name) {\n  const base = Object.hasOwn(PROVIDERS, name) ? PROVIDERS[name] : null;\n  if (!base) throw new OAuthError(404, "不支持这种登录方式");\n  const p = {\n    ...base,\n    name,\n    clientId: process.env[`${name.toUpperCase()}_CLIENT_ID`] || "",\n    clientSecret: process.env[`${name.toUpperCase()}_CLIENT_SECRET`] || "",\n    redirectUri: `${PUBLIC_URL}/auth/${name}/callback`,\n  };\n  if (MOCK) Object.assign(p, { authUrl: `${MOCK}/${name}/authorize`, tokenUrl: `${MOCK}/${name}/token`, userUrl: `${MOCK}/${name}/user` });\n  if (!p.clientId || !p.clientSecret) throw new OAuthError(503, "这种登录方式还没有配置");\n  return p;\n}\n\nfunction loginUrl(name, state) {\n  const p = provider(name);\n  const q = new URLSearchParams({ client_id: p.clientId, redirect_uri: p.redirectUri, state, scope: p.scope, response_type: "code" });\n  return `${p.authUrl}?${q}`;\n}\n\n// 和对方通信：要求返回 JSON，带上 User-Agent（GitHub 要求），检查状态码\nasync function fetchJSON(url, options) {\n  const res = await fetch(url, {\n    ...options,\n    headers: { Accept: "application/json", "User-Agent": "zixishi", ...options.headers },\n    signal: AbortSignal.timeout(15000),\n  });\n  if (!res.ok) throw new Error(`${url} 返回状态码 ${res.status}`);\n  return res.json();\n}\n\n// 根据对方的名字生成用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符；重试时加随机数字\nfunction usernameFor(p, name, retry) {\n  let base = p.prefix + String(name || "").replace(/[^A-Za-z0-9_]/g, "");\n  if (base.length <= p.prefix.length) base = p.prefix + "user";\n  return retry > 0 ? base.slice(0, 15) + crypto.randomInt(1000, 10000) : base.slice(0, 20);\n}\n\n// 回调：用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌\nasync function callback(name, code) {\n  const p = provider(name);\n  let info;\n  try {\n    const token = await fetchJSON(p.tokenUrl, {\n      method: "POST",\n      headers: { "Content-Type": "application/x-www-form-urlencoded" },\n      body: new URLSearchParams({ client_id: p.clientId, client_secret: p.clientSecret, code: code || "", redirect_uri: p.redirectUri, grant_type: "authorization_code" }),\n    });\n    if (!token.access_token) throw new Error("没有拿到 access_token");\n    info = await fetchJSON(p.userUrl, { headers: { Authorization: `Bearer ${token.access_token}` } });\n  } catch (err) {\n    console.error("第三方登录失败：", err);\n    throw new OAuthError(502, "第三方登录失败，请稍后再试");\n  }\n  const id = info[p.idField];\n  if (id === undefined || id === null || id === "") throw new OAuthError(502, "第三方登录失败，请稍后再试");\n\n  let user = oauthDb.findUserByOAuth(name, String(id));\n  for (let retry = 0; !user && retry < 5; retry++) {\n    try {\n      user = oauthDb.createOAuthUser(usernameFor(p, info[p.nameField], retry), name, String(id));\n    } catch (err) {\n      if (!(err instanceof users.UsernameTakenError)) throw err;\n    }\n  }\n  if (!user) throw new OAuthError(502, "第三方登录失败，请稍后再试");\n  const session = crypto.randomBytes(32).toString("hex");\n  users.createSession(session, user.id, Date.now() + SESSION_TTL);\n  return session;\n}\n\nmodule.exports = { OAuthError, loginUrl, callback };\n\n// src/routes/oauth.js\nconst express = require("express");\nconst crypto = require("node:crypto");\nconst oauth = require("../services/oauth");\nconst { SESSION_TTL } = require("../services/auth");\n\nconst router = express.Router();\nconst STATE = { httpOnly: true, sameSite: "lax", path: "/auth" };\n\nfunction fail(err, res, next) {\n  if (err instanceof oauth.OAuthError) return res.status(err.status).json({ error: err.message });\n  next(err);\n}\n\nrouter.get("/:provider/login", (req, res, next) => {\n  try {\n    const state = crypto.randomBytes(16).toString("hex");\n    const target = oauth.loginUrl(req.params.provider, state);\n    res.cookie("oauth_state", state, { ...STATE, maxAge: 10 * 60 * 1000 });\n    res.redirect(302, target);\n  } catch (err) {\n    fail(err, res, next);\n  }\n});\n\nrouter.get("/:provider/callback", async (req, res, next) => {\n  const expected = req.cookies.oauth_state;\n  if (!expected || expected !== req.query.state) {\n    return res.status(400).json({ error: "登录请求已过期或不合法，请重新登录" });\n  }\n  res.clearCookie("oauth_state", STATE);\n  try {\n    const token = await oauth.callback(req.params.provider, req.query.code);\n    res.cookie("session", token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: SESSION_TTL });\n    res.redirect(303, "/");\n  } catch (err) {\n    fail(err, res, next);\n  }\n});\n\nmodule.exports = router;\n\n// app.js：在 app.use("/api", notFound) 前面挂上\napp.use("/auth", require("./src/routes/oauth"));\n\n// src/services/auth.js：verifyPassword 的第一行加上，第三方登录的用户没有密码，直接算错\nif (!stored.includes(":")) return false;',explain:[{at:'// src/services/oauth.js',to:'const { SESSION_TTL } = require("./auth");',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、发请求的小工具、生成用户名。最后的 callback 要你写。'},{at:'class OAuthError extends Error {',to:'this.status = status;',text:'业务错误带上状态码：不支持 404、没配置 503、和对方通信失败 502。'},{at:'const PROVIDERS = {',to:'};',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'const MOCK =',to:'const PUBLIC_URL =',text:'测试用的假服务地址；网站自己的地址（拼回调地址用），默认 http://localhost:8080，上线后改成真实域名。'},{at:'function provider(name) {',to:'return p;',text:'Object.hasOwn 判断这个名字是不是 PROVIDERS 自己的属性（避免 "toString" 这种名字取到对象自带的东西）。应用编号和密钥按 GITHUB_CLIENT_ID 这样的名字从环境变量读取；Object.assign 把假服务的地址覆盖上去。'},{at:'function loginUrl(name, state) {',to:'return `${p.authUrl}?${q}`;',text:'拼出授权页的地址，URLSearchParams 会自动编码参数。'},{at:'async function fetchJSON(url, options) {',to:'return res.json();',text:'和对方通信的小工具：要求返回 JSON（GitHub 默认返回表单格式），带上 User-Agent，15 秒超时，检查状态码。'},{at:'function usernameFor(p, name, retry) {',to:'return retry > 0 ?',text:'生成用户名：去掉不合规的字符，最多 20 个字符；名字被占用时取前 15 个字符，再加一个 4 位随机数。'},{at:'async function callback(name, code) {',to:'let info;',text:'取出提供方的配置。'},{at:'try {',to:'throw new OAuthError(502, "第三方登录失败，请稍后再试");',text:'用授权码换令牌（OAuth 规定正文是表单格式，URLSearchParams 作为 body 时 fetch 会按表单发送），再用令牌取用户信息。client_secret 只在这里出现，浏览器看不到。任何一步失败都记日志、返回 502。'},{at:'const id = info[p.idField];',to:'if (id === undefined',text:'对方的用户编号，没有就是出错了。'},{at:'let user = oauthDb.findUserByOAuth(name, String(id));',to:'if (!user) throw new OAuthError(502,',text:'先找对应关系；第一次来就新建账号，用户名被占用时换一个带随机数字的名字再试。for 循环的条件里写了 !user，建成功就停。'},{at:'const session = crypto.randomBytes(32).toString("hex");',to:'return session;',text:'和密码登录一样：生成会话令牌、保存会话。'},{at:'module.exports = { OAuthError, loginUrl, callback };',text:'导出。'},{at:'// src/routes/oauth.js',to:'const STATE = { httpOnly: true, sameSite: "lax", path: "/auth" };',text:'第三方登录的两个地址，已经给出。它们是给浏览器直接打开的（会重定向），所以挂在 /auth 而不是 /api 下面。STATE 是 state Cookie 的选项：只在 /auth 下面有效。'},{at:'function fail(err, res, next) {',to:'next(err);',text:'业务错误按状态码返回，其他交给错误处理中间件。'},{at:'router.get("/:provider/login",',to:'fail(err, res, next);',text:'登录地址：生成随机 state，一份进 Cookie（10 分钟过期），一份拼进授权地址，然后 302 把浏览器带过去。SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。'},{at:'router.get("/:provider/callback",',to:'res.clearCookie("oauth_state", STATE);',text:'回调：Cookie 里的 state 和地址里的必须一致，防止登录 CSRF；用过就删。'},{at:'try {',to:'fail(err, res, next);',text:'换令牌、取用户、建会话都交给业务逻辑层；成功后设置会话 Cookie（和第 9 关一样的选项），303 回到首页。'},{at:'module.exports = router;',text:'导出路由。'},{at:'app.use("/auth", require("./src/routes/oauth"));',text:'挂在 /auth 下面。'},{at:'if (!stored.includes(":")) return false;',text:'第三方登录的用户密码哈希是空字符串，原来的 verifyPassword 拆不出盐和哈希会报错（变成 500）。没有冒号就直接返回“密码不对”。'}]}},python:{practice:{steps:['新建 app/services/oauth.py（代码第一部分），读懂已经给出的部分，补完 TODO。','新建 app/routers/oauth.py，按最后几行修改 main.py 和 app/services/auth.py 的 verify_password。','按验收卡片设置环境变量重启，浏览器打开 /auth/github/login 看看会跳到哪里。'],expect:'GET /auth/github/login\n→ 302 Location: http://127.0.0.1:8091/github/authorize?client_id=gh-id&redirect_uri=…&state=…'},code:'# app/services/oauth.py\nimport logging\nimport os\nimport re\nimport secrets\nimport time\n\nimport httpx\n\nfrom app import oauth_db, users\nfrom app.services.auth import SESSION_TTL\n\nlog = logging.getLogger("zixishi")\n\nPROVIDERS = {\n    "github": {"auth_url": "https://github.com/login/oauth/authorize",\n               "token_url": "https://github.com/login/oauth/access_token",\n               "user_url": "https://api.github.com/user",\n               "scope": "read:user", "prefix": "gh_", "id_field": "id", "name_field": "login"},\n    "google": {"auth_url": "https://accounts.google.com/o/oauth2/v2/auth",\n               "token_url": "https://oauth2.googleapis.com/token",\n               "user_url": "https://openidconnect.googleapis.com/v1/userinfo",\n               "scope": "openid profile email", "prefix": "gg_", "id_field": "sub", "name_field": "name"},\n}\nMOCK = os.getenv("OAUTH_MOCK_URL", "").rstrip("/")\nPUBLIC_URL = os.getenv("PUBLIC_URL", "http://localhost:8080").rstrip("/")\n\n\nclass OAuthError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\ndef provider(name):\n    """按名字取出提供方的完整配置：应用编号和密钥来自环境变量；设置了 OAUTH_MOCK_URL 时地址换成假服务"""\n    if name not in PROVIDERS:\n        raise OAuthError(404, "不支持这种登录方式")\n    p = dict(PROVIDERS[name], name=name,\n             client_id=os.getenv(f"{name.upper()}_CLIENT_ID", ""),\n             client_secret=os.getenv(f"{name.upper()}_CLIENT_SECRET", ""),\n             redirect_uri=f"{PUBLIC_URL}/auth/{name}/callback")\n    if MOCK:\n        p.update(auth_url=f"{MOCK}/{name}/authorize", token_url=f"{MOCK}/{name}/token", user_url=f"{MOCK}/{name}/user")\n    if not p["client_id"] or not p["client_secret"]:\n        raise OAuthError(503, "这种登录方式还没有配置")\n    return p\n\n\ndef login_url(name, state):\n    p = provider(name)\n    query = httpx.QueryParams(client_id=p["client_id"], redirect_uri=p["redirect_uri"], state=state,\n                              scope=p["scope"], response_type="code")\n    return f"{p[\'auth_url\']}?{query}"\n\n\ndef username_for(p, name, retry):\n    """根据对方的名字生成用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符；重试时加随机数字"""\n    base = p["prefix"] + re.sub(r"[^A-Za-z0-9_]", "", str(name or ""))\n    if len(base) <= len(p["prefix"]):\n        base = p["prefix"] + "user"\n    return base[:15] + str(secrets.randbelow(9000) + 1000) if retry else base[:20]\n\n\ndef callback(name, code):\n    """用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌"""\n    # TODO 1：取出提供方；httpx.post 表单（data=）到 token_url：client_id、client_secret、code、redirect_uri、grant_type=authorization_code，\n    #         请求头 Accept: application/json 和 User-Agent；取出 access_token，再带 Authorization: Bearer 令牌 GET user_url；\n    #         对方的用户编号是 info[id_field]（转成 str）；任何一步出错都记日志并抛出 OAuthError(502, "第三方登录失败，请稍后再试")\n    # TODO 2：oauth_db.find_user_by_oauth 找已有用户；没有就用 username_for 生成用户名 create_oauth_user 新建，\n    #         遇到 users.UsernameTaken 换个名字重试，最多 5 次\n    # TODO 3：secrets.token_hex(32) 生成会话令牌，users.create_session 保存（过期时间 int(time.time()) + SESSION_TTL），返回令牌\n    return ""\n\n# app/routers/oauth.py\nimport secrets\n\nfrom fastapi import APIRouter, Request\nfrom fastapi.responses import JSONResponse, RedirectResponse\n\nfrom app.services import oauth\nfrom app.services.auth import SESSION_TTL\n\nrouter = APIRouter(prefix="/auth")\n\n\n@router.get("/{name}/login")\ndef login(name: str):\n    state = secrets.token_hex(16)\n    response = RedirectResponse(oauth.login_url(name, state), status_code=302)\n    response.set_cookie("oauth_state", state, max_age=600, path="/auth", httponly=True, samesite="lax")\n    return response\n\n\n@router.get("/{name}/callback")\ndef callback(name: str, request: Request, code: str = "", state: str = ""):\n    expected = request.cookies.get("oauth_state")\n    if not expected or expected != state:\n        return JSONResponse({"error": "登录请求已过期或不合法，请重新登录"}, status_code=400)\n    token = oauth.callback(name, code)\n    response = RedirectResponse("/", status_code=303)\n    response.delete_cookie("oauth_state", path="/auth")\n    response.set_cookie("session", token, max_age=SESSION_TTL, httponly=True, samesite="lax")\n    return response\n\n# main.py：导入 from app.routers import oauth as oauth_routes 和 from app.services.oauth import OAuthError；\n# 挂上路由（写在兜底路由和静态目录前面），并像之前一样给 OAuthError 加一个处理函数\napp.include_router(oauth_routes.router)\n\n\n@app.exception_handler(OAuthError)\nasync def oauth_error(request: Request, exc: OAuthError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)\n\n# app/services/auth.py：verify_password 的第一行加上，第三方登录的用户没有密码，直接算错\n    if ":" not in stored:\n        return False',explain:[{at:'# app/services/oauth.py',to:'log = logging.getLogger("zixishi")',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、生成用户名。最后的 callback 要你写。'},{at:'PROVIDERS = {',to:'"scope": "openid profile email", "prefix": "gg_", "id_field": "sub", "name_field": "name"},',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'MOCK =',to:'PUBLIC_URL =',text:'测试用的假服务地址；网站自己的地址（拼回调地址用），默认 http://localhost:8080，上线后改成真实域名。'},{at:'class OAuthError(Exception):',to:'self.message = message',text:'业务错误带上状态码：不支持 404、没配置 503、和对方通信失败 502。'},{at:'def provider(name):',to:'return p',text:'dict(原字典, 键=值…) 复制一份配置再加上新的键；应用编号和密钥按 GITHUB_CLIENT_ID 这样的名字从环境变量读取；update 把假服务的地址覆盖上去。'},{at:'def login_url(name, state):',to:'return f"{p[\'auth_url\']}?{query}"',text:'拼出授权页的地址，QueryParams 会自动编码参数。'},{at:'def username_for(p, name, retry):',to:'return base[:15]',text:'生成用户名：去掉不合规的字符，最多 20 个字符；名字被占用时取前 15 个字符，再加一个 4 位随机数（secrets 生成）。'},{at:'def callback(name, code):',to:'return ""',text:'回调的核心流程，要你补全。'},{at:'# app/routers/oauth.py',to:'router = APIRouter(prefix="/auth")',text:'第三方登录的两个地址，已经给出。它们是给浏览器直接打开的（会重定向），所以挂在 /auth 而不是 /api 下面。'},{at:'@router.get("/{name}/login")',to:'return response',text:'登录地址：生成随机 state，一份拼进授权地址，一份放进 Cookie（只在 /auth 下有效，10 分钟过期），然后 302 把浏览器带到授权页。SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。'},{at:'@router.get("/{name}/callback")',to:'return JSONResponse({"error": "登录请求已过期或不合法，请重新登录"}, status_code=400)',text:'回调：Cookie 里的 state 和地址里的必须一致，防止登录 CSRF。'},{at:'token = oauth.callback(name, code)',to:'return response',text:'换令牌、取用户、建会话交给业务逻辑层；成功后删掉 state Cookie，设置会话 Cookie，303 回到首页。'},{at:'app.include_router(oauth_routes.router)',text:'挂上路由。'},{at:'@app.exception_handler(OAuthError)',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'业务错误按状态码返回。'},{at:'if ":" not in stored:',to:'return False',text:'第三方登录的用户密码哈希是空字符串，原来的 verify_password 拆不出盐和哈希会报错（变成 500）。没有冒号就直接返回“密码不对”。'}],solution:{code:'# app/services/oauth.py\nimport logging\nimport os\nimport re\nimport secrets\nimport time\n\nimport httpx\n\nfrom app import oauth_db, users\nfrom app.services.auth import SESSION_TTL\n\nlog = logging.getLogger("zixishi")\n\nPROVIDERS = {\n    "github": {"auth_url": "https://github.com/login/oauth/authorize",\n               "token_url": "https://github.com/login/oauth/access_token",\n               "user_url": "https://api.github.com/user",\n               "scope": "read:user", "prefix": "gh_", "id_field": "id", "name_field": "login"},\n    "google": {"auth_url": "https://accounts.google.com/o/oauth2/v2/auth",\n               "token_url": "https://oauth2.googleapis.com/token",\n               "user_url": "https://openidconnect.googleapis.com/v1/userinfo",\n               "scope": "openid profile email", "prefix": "gg_", "id_field": "sub", "name_field": "name"},\n}\nMOCK = os.getenv("OAUTH_MOCK_URL", "").rstrip("/")\nPUBLIC_URL = os.getenv("PUBLIC_URL", "http://localhost:8080").rstrip("/")\n\n\nclass OAuthError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\ndef provider(name):\n    """按名字取出提供方的完整配置：应用编号和密钥来自环境变量；设置了 OAUTH_MOCK_URL 时地址换成假服务"""\n    if name not in PROVIDERS:\n        raise OAuthError(404, "不支持这种登录方式")\n    p = dict(PROVIDERS[name], name=name,\n             client_id=os.getenv(f"{name.upper()}_CLIENT_ID", ""),\n             client_secret=os.getenv(f"{name.upper()}_CLIENT_SECRET", ""),\n             redirect_uri=f"{PUBLIC_URL}/auth/{name}/callback")\n    if MOCK:\n        p.update(auth_url=f"{MOCK}/{name}/authorize", token_url=f"{MOCK}/{name}/token", user_url=f"{MOCK}/{name}/user")\n    if not p["client_id"] or not p["client_secret"]:\n        raise OAuthError(503, "这种登录方式还没有配置")\n    return p\n\n\ndef login_url(name, state):\n    p = provider(name)\n    query = httpx.QueryParams(client_id=p["client_id"], redirect_uri=p["redirect_uri"], state=state,\n                              scope=p["scope"], response_type="code")\n    return f"{p[\'auth_url\']}?{query}"\n\n\ndef username_for(p, name, retry):\n    """根据对方的名字生成用户名：前缀加名字，只保留字母、数字、下划线，最长 20 个字符；重试时加随机数字"""\n    base = p["prefix"] + re.sub(r"[^A-Za-z0-9_]", "", str(name or ""))\n    if len(base) <= len(p["prefix"]):\n        base = p["prefix"] + "user"\n    return base[:15] + str(secrets.randbelow(9000) + 1000) if retry else base[:20]\n\n\ndef callback(name, code):\n    """用授权码换令牌、取用户信息、找到或新建用户，最后创建会话，返回会话令牌"""\n    p = provider(name)\n    headers = {"Accept": "application/json", "User-Agent": "zixishi"}\n    try:\n        token = httpx.post(p["token_url"], headers=headers, timeout=15, data={\n            "client_id": p["client_id"], "client_secret": p["client_secret"], "code": code,\n            "redirect_uri": p["redirect_uri"], "grant_type": "authorization_code"})\n        token.raise_for_status()\n        access = token.json()["access_token"]\n        info = httpx.get(p["user_url"], headers={**headers, "Authorization": f"Bearer {access}"}, timeout=15)\n        info.raise_for_status()\n        provider_user_id = str(info.json()[p["id_field"]])\n        display_name = info.json().get(p["name_field"])\n    except Exception:\n        log.exception("第三方登录失败")\n        raise OAuthError(502, "第三方登录失败，请稍后再试") from None\n\n    user = oauth_db.find_user_by_oauth(name, provider_user_id)\n    for retry in range(5):\n        if user:\n            break\n        try:\n            user = oauth_db.create_oauth_user(username_for(p, display_name, retry), name, provider_user_id)\n        except users.UsernameTaken:\n            pass\n    if not user:\n        raise OAuthError(502, "第三方登录失败，请稍后再试")\n    session = secrets.token_hex(32)\n    users.create_session(session, user["id"], int(time.time()) + SESSION_TTL)\n    return session\n\n# app/routers/oauth.py\nimport secrets\n\nfrom fastapi import APIRouter, Request\nfrom fastapi.responses import JSONResponse, RedirectResponse\n\nfrom app.services import oauth\nfrom app.services.auth import SESSION_TTL\n\nrouter = APIRouter(prefix="/auth")\n\n\n@router.get("/{name}/login")\ndef login(name: str):\n    state = secrets.token_hex(16)\n    response = RedirectResponse(oauth.login_url(name, state), status_code=302)\n    response.set_cookie("oauth_state", state, max_age=600, path="/auth", httponly=True, samesite="lax")\n    return response\n\n\n@router.get("/{name}/callback")\ndef callback(name: str, request: Request, code: str = "", state: str = ""):\n    expected = request.cookies.get("oauth_state")\n    if not expected or expected != state:\n        return JSONResponse({"error": "登录请求已过期或不合法，请重新登录"}, status_code=400)\n    token = oauth.callback(name, code)\n    response = RedirectResponse("/", status_code=303)\n    response.delete_cookie("oauth_state", path="/auth")\n    response.set_cookie("session", token, max_age=SESSION_TTL, httponly=True, samesite="lax")\n    return response\n\n# main.py：导入 from app.routers import oauth as oauth_routes 和 from app.services.oauth import OAuthError；\n# 挂上路由（写在兜底路由和静态目录前面），并像之前一样给 OAuthError 加一个处理函数\napp.include_router(oauth_routes.router)\n\n\n@app.exception_handler(OAuthError)\nasync def oauth_error(request: Request, exc: OAuthError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)\n\n# app/services/auth.py：verify_password 的第一行加上，第三方登录的用户没有密码，直接算错\n    if ":" not in stored:\n        return False',explain:[{at:'# app/services/oauth.py',to:'log = logging.getLogger("zixishi")',text:'第三方登录的业务规则。大部分已经给出：提供方的配置、拼授权地址、生成用户名。最后的 callback 要你写。'},{at:'PROVIDERS = {',to:'"scope": "openid profile email", "prefix": "gg_", "id_field": "sub", "name_field": "name"},',text:'两个提供方的默认配置。GitHub 的用户信息里编号叫 id、名字叫 login；Google 的编号叫 sub、名字叫 name。'},{at:'MOCK =',to:'PUBLIC_URL =',text:'测试用的假服务地址；网站自己的地址（拼回调地址用），默认 http://localhost:8080，上线后改成真实域名。'},{at:'class OAuthError(Exception):',to:'self.message = message',text:'业务错误带上状态码：不支持 404、没配置 503、和对方通信失败 502。'},{at:'def provider(name):',to:'return p',text:'dict(原字典, 键=值…) 复制一份配置再加上新的键；应用编号和密钥按 GITHUB_CLIENT_ID 这样的名字从环境变量读取；update 把假服务的地址覆盖上去。'},{at:'def login_url(name, state):',to:'return f"{p[\'auth_url\']}?{query}"',text:'拼出授权页的地址，QueryParams 会自动编码参数。'},{at:'def username_for(p, name, retry):',to:'return base[:15]',text:'生成用户名：去掉不合规的字符，最多 20 个字符；名字被占用时取前 15 个字符，再加一个 4 位随机数（secrets 生成）。'},{at:'def callback(name, code):',to:'headers = {"Accept": "application/json", "User-Agent": "zixishi"}',text:'取出提供方；要求返回 JSON（GitHub 默认返回表单格式），带上 GitHub 要求的 User-Agent。'},{at:'try:',to:'raise OAuthError(502, "第三方登录失败，请稍后再试") from None',text:'用授权码换令牌（data= 按表单格式发送，OAuth 规定的），再用令牌取用户信息。client_secret 只在这里出现，浏览器看不到。任何一步出错（状态码不对、没有字段、超时）都记日志、返回 502。'},{at:'user = oauth_db.find_user_by_oauth(name, provider_user_id)',to:'raise OAuthError(502, "第三方登录失败，请稍后再试")',text:'先找对应关系；第一次来就新建账号，用户名被占用时换一个带随机数字的名字再试。'},{at:'session = secrets.token_hex(32)',to:'return session',text:'和密码登录一样：生成会话令牌、保存会话。'},{at:'# app/routers/oauth.py',to:'router = APIRouter(prefix="/auth")',text:'第三方登录的两个地址，已经给出。它们是给浏览器直接打开的（会重定向），所以挂在 /auth 而不是 /api 下面。'},{at:'@router.get("/{name}/login")',to:'return response',text:'登录地址：生成随机 state，一份拼进授权地址，一份放进 Cookie（只在 /auth 下有效，10 分钟过期），然后 302 把浏览器带到授权页。SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。'},{at:'@router.get("/{name}/callback")',to:'return JSONResponse({"error": "登录请求已过期或不合法，请重新登录"}, status_code=400)',text:'回调：Cookie 里的 state 和地址里的必须一致，防止登录 CSRF。'},{at:'token = oauth.callback(name, code)',to:'return response',text:'换令牌、取用户、建会话交给业务逻辑层；成功后删掉 state Cookie，设置会话 Cookie，303 回到首页。'},{at:'app.include_router(oauth_routes.router)',text:'挂上路由。'},{at:'@app.exception_handler(OAuthError)',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'业务错误按状态码返回。'},{at:'if ":" not in stored:',to:'return False',text:'第三方登录的用户密码哈希是空字符串，原来的 verify_password 拆不出盐和哈希会报错（变成 500）。没有冒号就直接返回“密码不对”。'}]}}}},
  {title:'任务三：登录地址和回调',body:'处理请求的层：登录地址生成 state 并重定向；回调地址检查 state，调用业务逻辑层，设置会话 Cookie 后回到首页。（Node.js 和 Python 在任务二里已经一起写了。）',variants:{go:{practice:{steps:['新建 internal/handler/oauth.go，补完 TODO。','按最后的注释修改 handler.go 和 main.go。','按验收卡片设置环境变量，go run . 启动，浏览器打开 /auth/github/login 看看会跳到哪里。'],expect:'GET /auth/github/login\n→ 302 Location: http://127.0.0.1:8091/github/authorize?client_id=gh-id&redirect_uri=…&state=…'},code:'// internal/handler/oauth.go\npackage handler\n\nimport (\n    "crypto/rand"\n    "encoding/hex"\n    "errors"\n    "log"\n    "net/http"\n\n    "zixishi/internal/service"\n)\n\nconst stateCookie = "oauth_state"\n\nfunc (h *Handler) oauthError(w http.ResponseWriter, err error) {\n    switch {\n    case errors.Is(err, service.ErrUnknownProvider):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrProviderNotSetup):\n        writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrProviderFailed):\n        log.Printf("第三方登录失败：%v", err)\n        writeJSON(w, http.StatusBadGateway, map[string]string{"error": service.ErrProviderFailed.Error()})\n    default:\n        h.serverError(w, err)\n    }\n}\n\nfunc (h *Handler) oauthLogin(w http.ResponseWriter, r *http.Request) {\n    // TODO 1：用 crypto/rand 生成 16 个随机字节，hex 编码成 state；h.oauth.LoginURL(路径里的 provider, state)，出错交给 oauthError；\n    //         把 state 放进 Cookie（名字 stateCookie，Path "/auth"，MaxAge 600，HttpOnly，SameSite Lax）；302 重定向到授权地址\n}\n\nfunc (h *Handler) oauthCallback(w http.ResponseWriter, r *http.Request) {\n    // TODO 2：取出 state Cookie，和地址里的 state 比较，没有或不一致返回 400；然后删掉这个 Cookie（MaxAge -1）\n    // TODO 3：h.oauth.Callback(provider, 地址里的 code) 得到会话令牌，出错交给 oauthError；\n    //         成功后 setSession（第 9 关写的），303 重定向回首页 "/"\n}\n\n// 组装：Handler 加上字段 oauth *service.OAuthService，New 多一个参数（放在 ai 后面）；Routes 里加上：\n//     mux.HandleFunc("GET /auth/{provider}/login", h.oauthLogin)\n//     mux.HandleFunc("GET /auth/{provider}/callback", h.oauthCallback)\n// main.go 里在创建 auth 之后加上，再把 oauth 传给 handler.New：\nif err := us.MigrateOAuth(); err != nil {\n    log.Fatalf("创建第三方登录表失败：%v", err)\n}\noauth := service.NewOAuthService(us)',explain:[{at:'// internal/handler/oauth.go',to:'"zixishi/internal/service"',text:'第三方登录的两个地址。它们是给浏览器直接打开的（会重定向），所以不放在 /api 下面。'},{at:'const stateCookie = "oauth_state"',text:'保存 state 的 Cookie 名字。'},{at:'func (h *Handler) oauthError(',to:'h.serverError(w, err)',text:'把错误翻译成状态码：不支持 404，没配置 503，和对方通信失败 502（详细原因写进日志，给用户的只是笼统的提示）。'},{at:'func (h *Handler) oauthLogin(',text:'登录地址，要你补全。'},{at:'func (h *Handler) oauthCallback(',text:'回调地址，要你补全。'},{at:'if err := us.MigrateOAuth(); err != nil {',to:'oauth := service.NewOAuthService(us)',text:'建表，组装第三方登录服务。'}],solution:{code:'// internal/handler/oauth.go\npackage handler\n\nimport (\n    "crypto/rand"\n    "encoding/hex"\n    "errors"\n    "log"\n    "net/http"\n\n    "zixishi/internal/service"\n)\n\nconst stateCookie = "oauth_state"\n\nfunc (h *Handler) oauthError(w http.ResponseWriter, err error) {\n    switch {\n    case errors.Is(err, service.ErrUnknownProvider):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrProviderNotSetup):\n        writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrProviderFailed):\n        log.Printf("第三方登录失败：%v", err)\n        writeJSON(w, http.StatusBadGateway, map[string]string{"error": service.ErrProviderFailed.Error()})\n    default:\n        h.serverError(w, err)\n    }\n}\n\nfunc (h *Handler) oauthLogin(w http.ResponseWriter, r *http.Request) {\n    b := make([]byte, 16)\n    rand.Read(b)\n    state := hex.EncodeToString(b)\n    target, err := h.oauth.LoginURL(r.PathValue("provider"), state)\n    if err != nil {\n        h.oauthError(w, err)\n        return\n    }\n    http.SetCookie(w, &http.Cookie{Name: stateCookie, Value: state, Path: "/auth", MaxAge: 600,\n        HttpOnly: true, SameSite: http.SameSiteLaxMode})\n    http.Redirect(w, r, target, http.StatusFound)\n}\n\nfunc (h *Handler) oauthCallback(w http.ResponseWriter, r *http.Request) {\n    c, err := r.Cookie(stateCookie)\n    if err != nil || c.Value == "" || c.Value != r.URL.Query().Get("state") {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "登录请求已过期或不合法，请重新登录"})\n        return\n    }\n    http.SetCookie(w, &http.Cookie{Name: stateCookie, Value: "", Path: "/auth", MaxAge: -1})\n    token, err := h.oauth.Callback(r.PathValue("provider"), r.URL.Query().Get("code"))\n    if err != nil {\n        h.oauthError(w, err)\n        return\n    }\n    setSession(w, token)\n    http.Redirect(w, r, "/", http.StatusSeeOther)\n}\n\n// 组装：Handler 加上字段 oauth *service.OAuthService，New 多一个参数（放在 ai 后面）；Routes 里加上：\n//     mux.HandleFunc("GET /auth/{provider}/login", h.oauthLogin)\n//     mux.HandleFunc("GET /auth/{provider}/callback", h.oauthCallback)\n// main.go 里在创建 auth 之后加上，再把 oauth 传给 handler.New：\nif err := us.MigrateOAuth(); err != nil {\n    log.Fatalf("创建第三方登录表失败：%v", err)\n}\noauth := service.NewOAuthService(us)',explain:[{at:'// internal/handler/oauth.go',to:'"zixishi/internal/service"',text:'第三方登录的两个地址。它们是给浏览器直接打开的（会重定向），所以不放在 /api 下面。'},{at:'const stateCookie = "oauth_state"',text:'保存 state 的 Cookie 名字。'},{at:'func (h *Handler) oauthError(',to:'h.serverError(w, err)',text:'把错误翻译成状态码：不支持 404，没配置 503，和对方通信失败 502（详细原因写进日志，给用户的只是笼统的提示）。'},{at:'func (h *Handler) oauthLogin(',to:'state := hex.EncodeToString(b)',text:'生成随机的 state，必须用密码学安全的随机数。'},{at:'target, err := h.oauth.LoginURL(',to:'return',text:'拼出授权地址；不支持或没配置时返回错误。'},{at:'http.SetCookie(w, &http.Cookie{Name: stateCookie',to:'http.Redirect(w, r, target, http.StatusFound)',text:'state 放进 Cookie，只在 /auth 下面有效，10 分钟过期；SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。然后用 302 把浏览器带到授权页。'},{at:'func (h *Handler) oauthCallback(',to:'return',text:'检查 state：Cookie 里的和地址里的必须一致，防止登录 CSRF。'},{at:'http.SetCookie(w, &http.Cookie{Name: stateCookie, Value: ""',text:'state 用过一次就删掉。'},{at:'token, err := h.oauth.Callback(',to:'http.Redirect(w, r, "/", http.StatusSeeOther)',text:'换令牌、取用户、建会话都交给业务逻辑层；成功后设置会话 Cookie，回到首页。'},{at:'if err := us.MigrateOAuth(); err != nil {',to:'oauth := service.NewOAuthService(us)',text:'建表，组装第三方登录服务。'}]}},java:{practice:{steps:['新建 controller/OAuthController.java，补完 TODO。','按验收卡片设置环境变量重启，浏览器打开 /auth/github/login 看看会跳到哪里。'],expect:'GET /auth/github/login\n→ 302 Location: http://127.0.0.1:8091/github/authorize?client_id=gh-id&redirect_uri=…&state=…'},code:'// controller/OAuthController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.OAuthService;\nimport java.net.URI;\nimport java.security.SecureRandom;\nimport java.util.HexFormat;\nimport java.util.Map;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.ResponseCookie;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/auth")\npublic class OAuthController {\n\n    private final OAuthService oauth;\n    private final SecureRandom random = new SecureRandom();\n\n    public OAuthController(OAuthService oauth) {\n        this.oauth = oauth;\n    }\n\n    private static String cookie(String name, String value, String path, long maxAge) {\n        return ResponseCookie.from(name, value).httpOnly(true).sameSite("Lax").path(path).maxAge(maxAge).build().toString();\n    }\n\n    // TODO 1：GET /{provider}/login：用 random 生成 16 字节、HexFormat 编码成 state；oauth.loginUrl(provider, state) 拿到授权地址；\n    //         返回 302，Location 是授权地址，并用 cookie("oauth_state", state, "/auth", 600) 设置 state Cookie\n    // TODO 2：GET /{provider}/callback：@RequestParam 读出 code 和 state，@CookieValue 读出 oauth_state；\n    //         两个 state 不一致（或没有 Cookie）返回 400 和 {"error": "登录请求已过期或不合法，请重新登录"}；\n    //         oauth.callback 得到会话令牌；返回 303 回到 "/"，删掉 state Cookie（有效期 0），设置 session Cookie\n}',explain:[{at:'// controller/OAuthController.java',to:'import org.springframework.web.bind.annotation.*;',text:'第三方登录的两个地址。它们是给浏览器直接打开的（会重定向），所以放在 /auth 而不是 /api 下面。'},{at:'@RestController',to:'this.oauth = oauth;',text:'注入第三方登录服务。'},{at:'private static String cookie(',to:'return ResponseCookie.from(name, value)',text:'生成 Set-Cookie 的小工具：HttpOnly、SameSite=Lax。SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。'}],solution:{code:'// controller/OAuthController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.OAuthService;\nimport java.net.URI;\nimport java.security.SecureRandom;\nimport java.util.HexFormat;\nimport java.util.Map;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.ResponseCookie;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/auth")\npublic class OAuthController {\n\n    private final OAuthService oauth;\n    private final SecureRandom random = new SecureRandom();\n\n    public OAuthController(OAuthService oauth) {\n        this.oauth = oauth;\n    }\n\n    private static String cookie(String name, String value, String path, long maxAge) {\n        return ResponseCookie.from(name, value).httpOnly(true).sameSite("Lax").path(path).maxAge(maxAge).build().toString();\n    }\n\n    @GetMapping("/{provider}/login")\n    public ResponseEntity<Void> login(@PathVariable String provider) {\n        byte[] bytes = new byte[16];\n        random.nextBytes(bytes);\n        String state = HexFormat.of().formatHex(bytes);\n        String target = oauth.loginUrl(provider, state);\n        return ResponseEntity.status(302).location(URI.create(target))\n            .header(HttpHeaders.SET_COOKIE, cookie("oauth_state", state, "/auth", 600)).build();\n    }\n\n    @GetMapping("/{provider}/callback")\n    public ResponseEntity<?> callback(@PathVariable String provider, @RequestParam(defaultValue = "") String code,\n            @RequestParam(defaultValue = "") String state,\n            @CookieValue(name = "oauth_state", required = false) String expected) {\n        if (expected == null || expected.isEmpty() || !expected.equals(state)) {\n            return ResponseEntity.badRequest().body(Map.of("error", "登录请求已过期或不合法，请重新登录"));\n        }\n        String token = oauth.callback(provider, code);\n        return ResponseEntity.status(303).location(URI.create("/"))\n            .header(HttpHeaders.SET_COOKIE, cookie("oauth_state", "", "/auth", 0))\n            .header(HttpHeaders.SET_COOKIE, cookie("session", token, "/", AuthService.SESSION_TTL.toSeconds()))\n            .build();\n    }\n}',explain:[{at:'// controller/OAuthController.java',to:'import org.springframework.web.bind.annotation.*;',text:'第三方登录的两个地址。它们是给浏览器直接打开的（会重定向），所以放在 /auth 而不是 /api 下面。'},{at:'@RestController',to:'this.oauth = oauth;',text:'注入第三方登录服务。'},{at:'private static String cookie(',to:'return ResponseCookie.from(name, value)',text:'生成 Set-Cookie 的小工具：HttpOnly、SameSite=Lax。SameSite=Lax 的 Cookie 在“从 GitHub 跳回来”这种顶层跳转时会被带上。'},{at:'@GetMapping("/{provider}/login")',to:'.header(HttpHeaders.SET_COOKIE, cookie("oauth_state", state, "/auth", 600)).build();',text:'生成随机的 state，一份拼进授权地址，一份放进 Cookie（只在 /auth 下有效，10 分钟过期），然后 302 把浏览器带到授权页。不支持或没配置时，loginUrl 抛出的异常由 GlobalErrors 返回 404 或 503。'},{at:'@GetMapping("/{provider}/callback")',to:'return ResponseEntity.badRequest()',text:'回调：Cookie 里的 state 和地址里的必须一致，防止登录 CSRF。'},{at:'String token = oauth.callback(provider, code);',to:'.build();',text:'换令牌、取用户、建会话交给业务逻辑层；成功后删掉 state Cookie，设置会话 Cookie，303 回到首页。一个响应可以有多个 Set-Cookie 头。'}]}}}},
  {title:'任务四：登录页加上按钮',body:'登录页上加两个链接，点了就开始第三方登录。不需要 JavaScript：链接本身就是一次 GET 请求，后端会负责重定向。\n原生 HTML：加在 login.html 的表单下面；React：加在 LoginPage 的表单下面；模板渲染：加在登录页模板的表单下面。',practice:{steps:['把下面两个链接加到你的登录页上。','按验收卡片设置好环境变量，点“用 GitHub 登录”，会跳到假服务的地址（假服务不提供授权页，看到 404 是正常的）；配置了真实的 GitHub 应用后，就能走完整个流程。'],expect:'登录页上出现“用 GitHub 登录”“用 Google 登录”两个链接'},code:`<p>
  <a href="/auth/github/login">用 GitHub 登录</a>
  <a href="/auth/google/login">用 Google 登录</a>
</p>`,explain:[{at:'<p>',to:'</p>',text:'两个普通链接，指向登录地址。React 的 JSX 里写法一样。'}]},
  {title:'验收：用假的授权服务检查第三方登录',body:'验收脚本在本机 8091 端口启动一个“假的授权服务”，同时扮演 GitHub 和 Google。运行前，启动后端时要设置这些环境变量：\nOAUTH_MOCK_URL=http://127.0.0.1:8091\nGITHUB_CLIENT_ID=gh-id，GITHUB_CLIENT_SECRET=gh-secret\nGOOGLE_CLIENT_ID=gg-id，GOOGLE_CLIENT_SECRET=gg-secret\n脚本会像浏览器一样走一遍流程：打开登录地址、检查重定向和 state、带着 code 回调、确认登录成功；还会检查 state 不对时被拒绝、同一个 GitHub 用户第二次登录还是同一个账号。',practice:{steps:['停掉后端，设置好上面五个环境变量再启动（PowerShell 用 $env:名字="值"，多个用分号隔开）。','把下面的脚本保存为 checks/check_l15.py，运行 python checks/check_l15.py，直到全部 ✓。','想试真的 GitHub 登录：去掉 OAUTH_MOCK_URL，换成真实的 Client ID 和 Secret 重启，在页面上点“用 GitHub 登录”。','全部通过后提交：git add . 然后 git commit -m "第 15 关：GitHub、Google 登录"。不要提交真实的 Client Secret。'],expect:'✓ 健康检查仍然正常\n✓ 登录地址重定向到授权页，带上 client_id、redirect_uri、state\n✓ state 不对时拒绝回调\n✓ 回调成功后登录，用户名带 gh_ 前缀\n✓ 换令牌时带上了 code 和 client_secret\n✓ 同一个 GitHub 用户再登录还是同一个账号\n✓ Google 登录也能用\n✓ 不支持的提供方返回 404\n\n通过 8 / 8'},code:`import http.cookiejar
import json
import sys
import threading
import urllib.error
import urllib.parse
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
tokens = []
passed = 0


class FakeOAuth(BaseHTTPRequestHandler):
    """假的授权服务：/github/token、/github/user、/google/token、/google/user"""

    def do_POST(self):
        form = urllib.parse.parse_qs(self.rfile.read(int(self.headers.get("Content-Length", 0))).decode())
        tokens.append({k: v[0] for k, v in form.items()})
        self.reply({"access_token": "tok-" + form.get("code", [""])[0], "token_type": "bearer"})

    def do_GET(self):
        auth = self.headers.get("Authorization", "")
        if self.path.startswith("/github/user") and auth == "Bearer tok-c1":
            return self.reply({"id": 583231, "login": "octo-cat"})
        if self.path.startswith("/google/user") and auth == "Bearer tok-g1":
            return self.reply({"sub": "1093", "name": "Alice", "email": "alice@example.com"})
        self.send_response(401)
        self.end_headers()

    def reply(self, data):
        raw = json.dumps(data).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def log_message(self, *args):
        pass


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args):
        return None


threading.Thread(target=ThreadingHTTPServer(("127.0.0.1", 8091), FakeOAuth).serve_forever, daemon=True).start()


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def browser():
    jar = http.cookiejar.CookieJar()
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar), NoRedirect)

    def get(path):
        try:
            with opener.open(BASE + path, timeout=10) as r:
                return r.status, r.headers, r.read().decode()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read().decode()
        except OSError as e:
            sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")

    return get


def login(get, provider, code):
    """走一遍登录：打开登录地址，取出 state，再带着 code 回调；返回回调的状态码和 /api/me"""
    _, headers, _ = get(f"/auth/{provider}/login")
    query = urllib.parse.parse_qs(urllib.parse.urlparse(headers.get("Location", "")).query)
    state = query.get("state", [""])[0]
    status, _, _ = get(f"/auth/{provider}/callback?" + urllib.parse.urlencode({"code": code, "state": state}))
    _, _, me = get("/api/me")
    return status, json.loads(me or "{}")


get = browser()
status, _, body = get("/api/health")
check("健康检查仍然正常", status == 200 and json.loads(body) == {"status": "ok"})

status, headers, _ = get("/auth/github/login")
if status == 503:
    sys.exit("GitHub 登录还没有配置：启动后端前要设置 OAUTH_MOCK_URL 和 GITHUB_CLIENT_ID 等环境变量")
location = headers.get("Location", "")
query = urllib.parse.parse_qs(urllib.parse.urlparse(location).query)
check("登录地址重定向到授权页，带上 client_id、redirect_uri、state", status in (302, 303, 307)
      and location.startswith("http://127.0.0.1:8091/github/authorize") and query.get("client_id") == ["gh-id"]
      and query.get("redirect_uri", [""])[0].endswith("/auth/github/callback") and len(query.get("state", [""])[0]) >= 16)

status, _, _ = get("/auth/github/callback?code=c1&state=wrong")
check("state 不对时拒绝回调", status == 400)

status, me = login(get, "github", "c1")
check("回调成功后登录，用户名带 gh_ 前缀", status in (302, 303) and me.get("username", "").startswith("gh_"))
last = tokens[-1] if tokens else {}
check("换令牌时带上了 code 和 client_secret", last.get("code") == "c1" and last.get("client_secret") == "gh-secret")

_, again = login(browser(), "github", "c1")
check("同一个 GitHub 用户再登录还是同一个账号", again.get("id") == me.get("id") and me.get("id") is not None)

_, alice = login(browser(), "google", "g1")
check("Google 登录也能用", alice.get("username", "").startswith("gg_") and alice.get("id") != me.get("id"))

status, _, _ = get("/auth/twitter/login")
check("不支持的提供方返回 404", status == 404)

print(f"\\n通过 {passed} / 8")`,explain:[{at:'import http.cookiejar',to:'from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer',text:'和上一关一样，用 Python 自带的模块启动一个假服务。'},{at:'BASE = sys.argv[1]',to:'passed = 0',text:'服务地址；tokens 记下假服务收到的每次“换令牌”请求。'},{at:'class FakeOAuth(BaseHTTPRequestHandler):',to:'"""假的授权服务',text:'假的授权服务，同时扮演 GitHub 和 Google。'},{at:'def do_POST(self):',to:'self.reply({"access_token": "tok-"',text:'换令牌：OAuth 规定这个请求的正文是表单格式（a=1&b=2），parse_qs 解析它。记下收到的参数，返回 tok- 加 code 作为访问令牌。'},{at:'def do_GET(self):',to:'self.end_headers()',text:'取用户信息：令牌对了才返回。GitHub 的格式是 {"id", "login"}，Google 的是 {"sub", "name", "email"}，两边不一样。'},{at:'def reply(self, data):',to:'self.wfile.write(raw)',text:'发送 JSON 响应。'},{at:'def log_message(self, *args):',to:'pass',text:'不打印请求日志。'},{at:'class NoRedirect(urllib.request.HTTPRedirectHandler):',to:'return None',text:'让请求工具不要自动跟随重定向，这样才能看到 302 响应和 Location 响应头。'},{at:'threading.Thread(',text:'在后台线程里启动假服务。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'检查一项并打印结果。'},{at:'def browser():',to:'return get',text:'模拟一个浏览器：有自己的 Cookie 罐子，不自动跟随重定向。返回一个发 GET 请求的函数。'},{at:'def login(get, provider, code):',to:'return status, json.loads(me or "{}")',text:'走一遍登录流程：打开登录地址，从 Location 里取出 state（Cookie 已经存进罐子了），再带着 code 和 state 访问回调地址，最后查 /api/me。'},{at:'get = browser()',to:'check("健康检查仍然正常"',text:'健康检查。'},{at:'status, headers, _ = get("/auth/github/login")',to:'and query.get("redirect_uri", [""])[0].endswith("/auth/github/callback") and len(query.get("state", [""])[0]) >= 16)',text:'返回 503 说明没配置，提示后退出。否则检查重定向：去的是假服务的授权地址，带着正确的 client_id、回调地址，以及足够长的随机 state。'},{at:'status, _, _ = get("/auth/github/callback?code=c1&state=wrong")',to:'check("state 不对时拒绝回调"',text:'state 和 Cookie 里的对不上，必须拒绝。'},{at:'status, me = login(get, "github", "c1")',to:'check("换令牌时带上了 code 和 client_secret"',text:'正常登录：回调后重定向，/api/me 返回 gh_ 开头的新用户；后端换令牌时带上了 code 和应用密钥。'},{at:'_, again = login(browser(), "github", "c1")',to:'check("同一个 GitHub 用户再登录还是同一个账号"',text:'换一个新“浏览器”，同一个 GitHub 用户再登录一次，还是同一个账号。'},{at:'_, alice = login(browser(), "google", "g1")',to:'check("Google 登录也能用"',text:'Google 登录：用户名 gg_ 开头，是另一个账号。'},{at:'status, _, _ = get("/auth/twitter/login")',to:'check("不支持的提供方返回 404"',text:'没有配置的提供方名字，返回 404。'},{at:'print(f"\\n通过 {passed} / 8")',text:'打印总的通过数。'}]},
  {title:'这一关学到了什么',body:'一、OAuth 2.0 授权码流程：重定向到授权页 → 带着 code 回调 → 后端用 code 和 client_secret 换令牌 → 用令牌取用户信息；\n二、client_secret 和 access_token 只在后端和提供方之间传，浏览器只经过一次性的 code；\n三、state 防登录 CSRF：随机生成，存进 Cookie，回调时比对，用过就删；\n四、用第三方的“用户编号”对应我们的账号，不要用会变的用户名或邮箱；\n五、同一套流程，不同的提供方只是配置不同；外部服务用一个配置项换成假服务来测试。\n下一关做管理后台：只有管理员能增删改题目。'}
 ],quiz:[
 {id:'pj-oauth-1',q:'OAuth 授权码流程里，用 code 换 access_token 这一步应该由谁来做？',options:['后端带上 client_secret 去换','浏览器里的 JavaScript 去换','用户自己复制粘贴令牌过来','GitHub 主动把令牌推送过来'],why:['','浏览器拿不到也不应该拿到 client_secret。','用户不需要接触令牌。','需要我们主动用 code 去换。'],answer:0,explain:'换令牌需要 client_secret，它只能放在后端。浏览器只经过一次性的 code，就算被看到，没有密钥也换不到令牌。'},
 {id:'pj-oauth-2',type:'judge',q:'state 参数的作用是防止“登录 CSRF”：坏人诱导你用他的第三方账号登录我们的网站。',answer:true,explain:'正确。state 随机生成并存进你浏览器的 Cookie，回调时必须一致。坏人构造的回调地址里的 state 和你的 Cookie 对不上，就会被拒绝。'},
 {id:'pj-oauth-3',q:'第三方账号和我们的账号对应，应该用对方的哪个字段？',options:['对方的用户编号','对方的用户名 login','用户的邮箱地址','用户的头像地址'],why:['','用户名可以修改，改名后就对应不上了。','邮箱可以更换，也可能没有公开。','头像随时会换。'],answer:0,explain:'对方的用户编号永远不变，是唯一可靠的对应依据。用户名、邮箱只用来生成显示名。'},
 {id:'pj-oauth-4',q:'回调时 URL 里的 state 和 Cookie 里的不一致，后端应该返回？',options:['400，拒绝这次登录','200，照常登录','302，重新跳到授权页','500，服务器出错'],why:['','不一致说明请求不是本人发起的，不能登录。','自动重新跳转可能形成循环，也掩盖了问题。','这不是服务器的错误。'],answer:0,explain:'state 不一致是请求不合法，返回 400 并提示“登录请求已过期或不合法，请重新登录”。'},
 {id:'pj-oauth-5',type:'multi',q:'下面哪些信息只应该出现在后端，不能让浏览器看到？（多选）',options:['client_secret','access_token','回调时的 state 参数','授权页地址里的 client_id'],why:['','','state 本来就在地址和 Cookie 里，浏览器能看到，它的作用是比对。','client_id 是公开的，本来就写在授权页地址里。'],answers:[0,1],explain:'client_secret 是应用的密钥，access_token 能代表用户调用对方的接口，都只在后端使用。client_id 和 state 是公开的。'},
 {id:'pj-oauth-6',q:'第三方登录新建的用户，password_hash 存空字符串，效果是？',options:['用密码登录这个账号会失败','用户可以用空密码直接登录','数据库会拒绝插入这一行','第一次登录时必须设置密码'],why:['','空密码会先被“至少 8 位”的规则挡住，而且空字符串也不是合法的哈希。','password_hash 是 NOT NULL，空字符串满足要求。','我们没有做这个要求，以后可以加“设置密码”的功能。'],answer:0,explain:'空字符串不是合法的哈希，核对密码一定失败，这个账号只能通过第三方登录。注意核对函数要能处理这种情况，不能报错变成 500。'},
 {id:'pj-oauth-7',type:'fill',q:'OAuth 2.0 中，用户在授权页点“同意”后，带回到我们网站的一次性凭证叫 ＿。',accepted:['code','授权码','authorization code'],explain:'code（授权码）。它只能用一次、很快过期，必须配合 client_secret 才能换到 access_token。'},
 {id:'pj-oauth-8',type:'judge',q:'设置 OAUTH_MOCK_URL 把提供方的地址换成假服务，只是为了测试方便，线上环境不应该设置它。',answer:true,explain:'正确。假服务只用于开发和自动化测试。线上不设置这个变量，地址就是 GitHub、Google 的真实地址。'},
 {id:'pj-oauth-9',type:'short',q:'请按顺序说出 OAuth 2.0 授权码流程的四个步骤，并说明每一步发生在哪里（浏览器还是后端）。',reference:'一、我们的后端生成 state，把浏览器重定向到提供方的授权页（浏览器跳转）；二、用户在提供方那里同意后，浏览器被重定向回我们的回调地址，带上 code 和 state（浏览器跳转）；三、后端检查 state，用 code 和 client_secret 向提供方换 access_token（后端对提供方）；四、后端用 access_token 取用户信息，找到或新建账号并创建会话（后端对提供方）。',points:['重定向到授权页（带 client_id、redirect_uri、state）','用户同意后带 code 回调','后端用 code 和 client_secret 换令牌','后端用令牌取用户信息，登录或建号'],explain:'前两步是浏览器跳转，后两步只在后端和提供方之间进行，密钥和令牌不经过浏览器。'},
 {id:'pj-oauth-go-1',stack:'go',q:'Go 中 fmt.Errorf("%w：换令牌 %v", ErrProviderFailed, err) 里的 %w 有什么作用？',options:['包装错误，errors.Is 仍能认出','把错误信息里的字母都转成大写','让同一条错误信息只显示一次','忽略并且丢掉原来的那个错误'],why:['','%w 和大小写无关。','和显示次数无关。','正好相反，它保留了被包装的错误。'],answer:0,explain:'%w 表示“包装”：新错误带上了更多细节（写进日志），而 errors.Is(err, ErrProviderFailed) 仍然为真，上层可以据此返回 502。'},
 {id:'pj-oauth-java-1',stack:'java',q:'Spring 中用 LinkedMultiValueMap 作为 RestClient 的请求正文，并设置 contentType 为表单，效果是？',options:['按 a=1&b=2 的表单格式发送','按 JSON 格式发送请求正文','按 XML 格式发送请求正文','把参数全部拼到地址后面'],why:['','设置了表单的 contentType，就不会转成 JSON。','和 XML 无关。','参数在请求正文里，不在地址里。'],answer:0,explain:'OAuth 规定换令牌的请求正文是表单格式。MultiValueMap 配合 APPLICATION_FORM_URLENCODED，Spring 会把它编码成表单。'},
 {id:'pj-oauth-node-1',stack:'node',q:'Node.js 中 Object.hasOwn(PROVIDERS, name) 比 PROVIDERS[name] 好在哪里？',options:['不会取到 toString 等自带属性','查找提供方的速度会更快一些','可以忽略提供方名字的大小写','能自动创建还不存在的提供方'],why:['','速度差别可以忽略。','它区分大小写。','它只是判断，不会创建。'],answer:0,explain:'普通对象都“继承”了 toString、constructor 等属性，PROVIDERS["toString"] 会取到一个函数。hasOwn 只认对象自己定义的属性。'},
 {id:'pj-oauth-python-1',stack:'python',q:'Python 中 httpx.post(url, data={...}) 和 httpx.post(url, json={...}) 有什么区别？',options:['data 是表单格式，json 是 JSON','两者发出的请求完全一样','data 会把参数拼到地址里','json 不能用在 POST 请求里'],why:['','格式不同，Content-Type 也不同。','参数在请求正文里，拼到地址里的是 params=。','json= 常用于 POST。'],answer:0,explain:'OAuth 规定换令牌用表单格式，所以用 data=；调用大模型等 JSON 接口时用 json=。'},
]};
